// src/utils/detect.ts
var fs = __toESM(require("fs"));
var path = __toESM(require("path"));
function detectProject(cwd = process.cwd()) {
  let packageManager = "npm";
  let projectType = "unknown";
  let hasSrcDir = false;
  let currentDir = cwd;
  let baseDir = cwd;
  while (currentDir !== path.parse(currentDir).root) {
    if (fs.existsSync(path.join(currentDir, "package.json"))) {
      baseDir = currentDir;
      break;
    }
    currentDir = path.dirname(currentDir);
  }
  if (fs.existsSync(path.join(baseDir, "pnpm-lock.yaml"))) {
    packageManager = "pnpm";
  } else if (fs.existsSync(path.join(baseDir, "yarn.lock"))) {
    packageManager = "yarn";
  } else if (fs.existsSync(path.join(baseDir, "bun.lockb")) || fs.existsSync(path.join(baseDir, "bun.lock"))) {
    packageManager = "bun";
  }
  if (fs.existsSync(path.join(baseDir, "src"))) {
    hasSrcDir = true;
  }
  try {
    const packageJsonPath = path.join(baseDir, "package.json");
    if (fs.existsSync(packageJsonPath)) {
      const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, "utf8"));
      const deps = { ...packageJson.dependencies, ...packageJson.devDependencies };
      if (deps["next"]) {
        projectType = "next";
      } else if (deps["vite"] || deps["@tailwindcss/vite"]) {
        projectType = "vite";
      } else if (deps["react-scripts"]) {
        projectType = "cra";
      }
    }
  } catch (err) {
  }
  return {
    packageManager,
    projectType,
    hasSrcDir,
    baseDir
  };
}

