var templateMonolithCacaoPro = {
  name: "template-monolith-cacao-pro",
  dependencies: ["framer-motion", "lucide-react"],
  fileName: "template-monolith-cacao-pro.tsx",
  content: '"use client";\n\nimport React, { useEffect, useRef, useState, RefObject } from "react";\nimport {\n  motion,\n  AnimatePresence,\n  animate,\n  useInView,\n  useMotionTemplate,\n  useMotionValue,\n  useMotionValueEvent,\n  useReducedMotion,\n  useSpring,\n  useTransform,\n  MotionValue,\n} from "framer-motion";\nimport { ArrowRight, Check } from "lucide-react";\n\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Tokens & Physics\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nconst SPRING = { type: "spring", stiffness: 400, damping: 30, mass: 0.8 } as const;\nconst TILT = { stiffness: 260, damping: 24, mass: 0.6 } as const;\n\nconst SPECULAR =\n  "inset 0 1px 0 0 rgba(255, 255, 255, 0.12), 0 8px 32px -4px rgba(0, 0, 0, 0.5)";\n\ntype EditionKey = "criollo" | "gianduja" | "espresso";\n\nconst EDITIONS: Record<\n  EditionKey,\n  {\n    name: string;\n    sub: string;\n    cacao: number;\n    accent: string;\n    swatch: string;\n    notes: string;\n    price: number;\n  }\n> = {\n  criollo: {\n    name: "Obsidian Criollo",\n    sub: "Sur del Lago single-estate dark cacao with smoked alderwood salt.",\n    cacao: 85,\n    accent: "#f59e0b",\n    swatch: "#12100e",\n    notes: "Sur del Lago 85%, vanilla orchid, alderwood salt.",\n    price: 64,\n  },\n  gianduja: {\n    name: "Smoked Gianduja",\n    sub: "Roasted Piedmont hazelnut praline with slow-flowing molten core.",\n    cacao: 72,\n    accent: "#ea580c",\n    swatch: "#20140e",\n    notes: "Piedmont hazelnut, roasted cocoa nibs, oak smoke.",\n    price: 68,\n  },\n  espresso: {\n    name: "Gold Espresso",\n    sub: "Cold-brew Geisha infusion with micro-thin dark biscuit layers.",\n    cacao: 78,\n    accent: "#eab308",\n    swatch: "#18130e",\n    notes: "Geisha cold brew, 24K gold leaf flakes, Guayas cacao.",\n    price: 72,\n  },\n};\n\nconst PHASES = [\n  {\n    step: "01",\n    title: "Polyhedral basalt facets.",\n    body: "Cast from high-density granite molds into sharp geometric cuts. The dry surface provides mechanical anchoring for the glaze layer.",\n    figure: 12,\n    unit: " facets",\n    caption: "Geometric cuts",\n  },\n  {\n    step: "02",\n    title: "29.4\xB0C mirror glaze pour.",\n    body: "Poured at the exact lipid equilibrium curve. Dynamic surface tension guides the chocolate sheet over facet edges without teardrop pooling.",\n    figure: 29.4,\n    unit: "\xB0C",\n    caption: "Tempering window",\n  },\n  {\n    step: "03",\n    title: "Form V crystalline snap.",\n    body: "Controlled cooling locks cocoa butter into a dense beta-crystalline matrix. Produces an acoustic fracture and a chiaroscuro mirror finish.",\n    figure: 99.4,\n    unit: "%",\n    caption: "Specular reflection",\n  },\n] as const;\n\nconst WEIGHTS = [\n  { label: "340 g", multiplier: 1, serves: "Serves 4\u20136" },\n  { label: "680 g", multiplier: 1.75, serves: "Serves 8\u201312" },\n] as const;\n\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Scroll helpers (nearest scroll container inside modal or viewport)\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nfunction findScroller(el: HTMLElement | null): HTMLElement | null {\n  let p = el?.parentElement ?? null;\n  while (p) {\n    const o = getComputedStyle(p).overflowY;\n    if (o === "auto" || o === "scroll") return p;\n    p = p.parentElement;\n  }\n  return null;\n}\n\nfunction useViewHeight(ref: RefObject<HTMLElement | null>) {\n  const [h, setH] = useState(800);\n  useEffect(() => {\n    const el = ref.current;\n    if (!el) return;\n    const scroller = findScroller(el);\n    const read = () => setH(scroller ? scroller.clientHeight : window.innerHeight);\n    read();\n    if (scroller) {\n      const ro = new ResizeObserver(read);\n      ro.observe(scroller);\n      return () => ro.disconnect();\n    }\n    window.addEventListener("resize", read);\n    return () => window.removeEventListener("resize", read);\n  }, [ref]);\n  return h;\n}\n\nfunction useScrollProgress(\n  ref: RefObject<HTMLElement | null>,\n  kind: "leave" | "track",\n  viewH: number\n) {\n  const mv = useMotionValue(0);\n  useEffect(() => {\n    const el = ref.current;\n    if (!el) return;\n    const scroller = findScroller(el);\n    const update = () => {\n      const r = el.getBoundingClientRect();\n      const top = scroller ? scroller.getBoundingClientRect().top : 0;\n      const vh = scroller ? scroller.clientHeight : window.innerHeight;\n      const rel = r.top - top;\n      const total = kind === "track" ? r.height - vh : r.height;\n      mv.set(total > 0 ? Math.min(1, Math.max(0, -rel / total)) : 0);\n    };\n    update();\n    const target: HTMLElement | Window = scroller ?? window;\n    target.addEventListener("scroll", update, { passive: true });\n    window.addEventListener("resize", update);\n    return () => {\n      target.removeEventListener("scroll", update);\n      window.removeEventListener("resize", update);\n    };\n  }, [ref, kind, mv, viewH]);\n  return mv;\n}\n\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Micro Components\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nfunction SplitWords({\n  text,\n  className,\n  delay = 0,\n  onView = false,\n}: {\n  text: string;\n  className?: string;\n  delay?: number;\n  onView?: boolean;\n}) {\n  const words = text.split(" ");\n  return (\n    <span className={className} aria-label={text}>\n      {words.map((w, i) => (\n        <span\n          key={i}\n          aria-hidden\n          className="inline-block overflow-hidden align-bottom pb-[0.12em] -mb-[0.12em]"\n        >\n          <motion.span\n            className="inline-block"\n            initial={{ y: "115%" }}\n            {...(onView\n              ? { whileInView: { y: 0 }, viewport: { once: true, margin: "-10% 0px" } }\n              : { animate: { y: 0 } })}\n            transition={{ ...SPRING, delay: delay + i * 0.07 }}\n          >\n            {w}\n          </motion.span>\n          {i < words.length - 1 ? "\\u00A0" : ""}\n        </span>\n      ))}\n    </span>\n  );\n}\n\nfunction Reveal({\n  children,\n  delay = 0,\n  className,\n}: {\n  children: React.ReactNode;\n  delay?: number;\n  className?: string;\n}) {\n  const reduce = useReducedMotion();\n  return (\n    <motion.div\n      className={className}\n      initial={{ opacity: 0, y: reduce ? 0 : 28 }}\n      whileInView={{ opacity: 1, y: 0 }}\n      viewport={{ once: true, margin: "-8% 0px" }}\n      transition={{ ...SPRING, delay }}\n    >\n      {children}\n    </motion.div>\n  );\n}\n\nfunction Counter({\n  to,\n  suffix = "",\n  delay = 0,\n  duration = 1.8,\n  decimals = 0,\n}: {\n  to: number;\n  suffix?: string;\n  delay?: number;\n  duration?: number;\n  decimals?: number;\n}) {\n  const ref = useRef<HTMLSpanElement>(null);\n  const inView = useInView(ref, { once: true });\n  const reduce = useReducedMotion();\n  const [v, setV] = useState(0);\n\n  useEffect(() => {\n    if (!inView) return;\n    const c = animate(0, to, {\n      duration: reduce ? 0 : duration,\n      delay: reduce ? 0 : delay,\n      ease: [0.16, 1, 0.3, 1],\n      onUpdate: (x) => setV(x),\n    });\n    return () => c.stop();\n  }, [inView, to, delay, duration, reduce]);\n\n  const formatted = decimals > 0 ? v.toFixed(decimals) : Math.round(v).toLocaleString("en-US");\n\n  return (\n    <span ref={ref} className="tabular-nums">\n      {formatted}\n      {suffix}\n    </span>\n  );\n}\n\nfunction MagneticButton({\n  children,\n  onClick,\n  className,\n  style,\n}: {\n  children: React.ReactNode;\n  onClick: () => void;\n  className?: string;\n  style?: React.CSSProperties;\n}) {\n  const x = useSpring(0, { stiffness: 300, damping: 20, mass: 0.5 });\n  const y = useSpring(0, { stiffness: 300, damping: 20, mass: 0.5 });\n  return (\n    <motion.button\n      type="button"\n      onClick={onClick}\n      onPointerMove={(e) => {\n        const r = e.currentTarget.getBoundingClientRect();\n        x.set((e.clientX - (r.left + r.width / 2)) * 0.12);\n        y.set((e.clientY - (r.top + r.height / 2)) * 0.35);\n      }}\n      onPointerLeave={() => {\n        x.set(0);\n        y.set(0);\n      }}\n      whileTap={{ scale: 0.96 }}\n      transition={SPRING}\n      style={{ x, y, ...style }}\n      className={className}\n    >\n      {children}\n    </motion.button>\n  );\n}\n\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Signature Wow: Glaze Pour Stage with Pointer Chiaroscuro Raytracing\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nfunction GlazeStage({\n  progress,\n  accent,\n  isDark,\n  isMobile,\n}: {\n  progress: MotionValue<number>;\n  accent: string;\n  isDark: boolean;\n  isMobile: boolean;\n}) {\n  const canvasRef = useRef<HTMLCanvasElement>(null);\n  const containerRef = useRef<HTMLDivElement>(null);\n  const [size, setSize] = useState({ w: 520, h: 440 });\n\n  const ptrX = useSpring(260, { stiffness: 220, damping: 28 });\n  const ptrY = useSpring(140, { stiffness: 220, damping: 28 });\n\n  useEffect(() => {\n    if (!containerRef.current) return;\n    const ro = new ResizeObserver((entries) => {\n      for (const entry of entries) {\n        const { width, height } = entry.contentRect;\n        if (width > 0 && height > 0) {\n          setSize({ w: Math.round(width), h: Math.round(height) });\n        }\n      }\n    });\n    ro.observe(containerRef.current);\n    return () => ro.disconnect();\n  }, []);\n\n  useEffect(() => {\n    ptrX.set(size.w * 0.38);\n    ptrY.set(size.h * 0.28);\n  }, [size, ptrX, ptrY]);\n\n  useEffect(() => {\n    const canvas = canvasRef.current;\n    if (!canvas) return;\n    const ctx = canvas.getContext("2d");\n    if (!ctx) return;\n\n    let animId: number;\n    let running = true;\n\n    const render = () => {\n      if (!running) return;\n\n      const dpr = Math.min(window.devicePixelRatio || 1, 2);\n      const w = size.w;\n      const h = size.h;\n      canvas.width = w * dpr;\n      canvas.height = h * dpr;\n      ctx.resetTransform?.();\n      ctx.scale(dpr, dpr);\n\n      ctx.clearRect(0, 0, w, h);\n\n      const cx = w / 2;\n      const cy = h / 2 + 10;\n      const r = Math.min(w, h) * (isMobile ? 0.34 : 0.36);\n\n      const p = progress.get();\n      const topY = cy - r * 1.08;\n      const botY = cy + r * 0.96;\n      // Pour height progression tied to scroll\n      const pourY = topY + (botY - topY) * Math.min(1, Math.max(0, p * 1.25));\n\n      const lx = ptrX.get();\n      const ly = ptrY.get();\n\n      // Plinth pedestal\n      ctx.beginPath();\n      ctx.ellipse(cx, botY + 28, r * 1.15, r * 0.22, 0, 0, Math.PI * 2);\n      ctx.fillStyle = isDark ? "rgba(255, 255, 255, 0.02)" : "rgba(0, 0, 0, 0.03)";\n      ctx.fill();\n      ctx.strokeStyle = isDark ? "rgba(255, 255, 255, 0.08)" : "rgba(0, 0, 0, 0.08)";\n      ctx.lineWidth = 1;\n      ctx.stroke();\n\n      // Contact shadow\n      ctx.beginPath();\n      ctx.ellipse(cx, botY + 24, r * 0.78, r * 0.15, 0, 0, Math.PI * 2);\n      ctx.fillStyle = isDark ? "rgba(0, 0, 0, 0.55)" : "rgba(0, 0, 0, 0.16)";\n      ctx.fill();\n\n      // Polyhedral Monolith Vertices\n      const facetCount = 6;\n      const eqPoints: { x: number; y: number; z: number }[] = [];\n      const rot = 0.24;\n      for (let i = 0; i < facetCount; i++) {\n        const th = rot + (i * Math.PI * 2) / facetCount;\n        eqPoints.push({\n          x: cx + Math.cos(th) * r,\n          y: cy + Math.sin(th) * (r * 0.32),\n          z: Math.sin(th) * r,\n        });\n      }\n\n      const topPt = { x: cx, y: topY, z: 0 };\n      const botPt = { x: cx, y: botY, z: 0 };\n\n      const drawFacet = (\n        p1: { x: number; y: number; z: number },\n        p2: { x: number; y: number; z: number },\n        p3: { x: number; y: number; z: number },\n        normal: { x: number; y: number; z: number }\n      ) => {\n        if (normal.z <= -0.05) return;\n\n        const midY = (p1.y + p2.y + p3.y) / 3;\n        const midX = (p1.x + p2.x + p3.x) / 3;\n\n        const isGlazed = midY <= pourY;\n        const glazeRatio = Math.min(1, Math.max(0, (pourY - (midY - r * 0.25)) / (r * 0.5)));\n\n        const ldx = lx - midX;\n        const ldy = ly - midY;\n        const ldz = 160;\n        const lLen = Math.hypot(ldx, ldy, ldz) || 1;\n        const nx = ldx / lLen;\n        const ny = ldy / lLen;\n        const nz = ldz / lLen;\n\n        const diffuse = Math.max(0, normal.x * nx + normal.y * ny + normal.z * nz);\n        const spec = Math.pow(diffuse, isGlazed ? 22 : 6);\n\n        ctx.beginPath();\n        ctx.moveTo(p1.x, p1.y);\n        ctx.lineTo(p2.x, p2.y);\n        ctx.lineTo(p3.x, p3.y);\n        ctx.closePath();\n\n        if (isDark) {\n          if (glazeRatio > 0.75) {\n            const baseLum = 8 + diffuse * 14;\n            ctx.fillStyle = `rgb(${Math.round(baseLum + spec * 62)}, ${Math.round(baseLum + spec * 44)}, ${Math.round(baseLum + spec * 22)})`;\n          } else if (glazeRatio > 0.2) {\n            ctx.fillStyle = `rgb(${Math.round(14 + spec * 40)}, ${Math.round(12 + spec * 30)}, ${Math.round(10 + spec * 15)})`;\n          } else {\n            const baseLum = 18 + diffuse * 22;\n            ctx.fillStyle = `rgb(${Math.round(baseLum + spec * 12)}, ${Math.round(baseLum + spec * 10)}, ${Math.round(baseLum + spec * 8)})`;\n          }\n        } else {\n          if (glazeRatio > 0.75) {\n            const baseLum = 24 + diffuse * 30;\n            ctx.fillStyle = `rgb(${Math.round(baseLum + spec * 70)}, ${Math.round(baseLum + spec * 50)}, ${Math.round(baseLum + spec * 30)})`;\n          } else {\n            const baseLum = 60 + diffuse * 40;\n            ctx.fillStyle = `rgb(${Math.round(baseLum + spec * 20)}, ${Math.round(baseLum + spec * 16)}, ${Math.round(baseLum + spec * 12)})`;\n          }\n        }\n        ctx.fill();\n\n        const edgeGlow = spec > 0.55 && isGlazed;\n        ctx.strokeStyle = edgeGlow\n          ? accent\n          : isDark\n          ? "rgba(255, 255, 255, 0.12)"\n          : "rgba(0, 0, 0, 0.15)";\n        ctx.lineWidth = edgeGlow ? 1.6 : 1;\n        ctx.stroke();\n\n        if (spec > 0.72 && isGlazed) {\n          ctx.beginPath();\n          ctx.arc(midX, midY, 2.5, 0, Math.PI * 2);\n          ctx.fillStyle = "#ffffff";\n          ctx.fill();\n        }\n      };\n\n      const computeNormal = (\n        p1: { x: number; y: number; z: number },\n        p2: { x: number; y: number; z: number },\n        p3: { x: number; y: number; z: number }\n      ) => {\n        const v1x = p2.x - p1.x, v1y = p2.y - p1.y, v1z = p2.z - p1.z;\n        const v2x = p3.x - p1.x, v2y = p3.y - p1.y, v2z = p3.z - p1.z;\n        const nx = v1y * v2z - v1z * v2y;\n        const ny = v1z * v2x - v1x * v2z;\n        const nz = v1x * v2y - v1y * v2x;\n        const len = Math.hypot(nx, ny, nz) || 1;\n        return { x: nx / len, y: ny / len, z: nz / len };\n      };\n\n      // Top Pyramid\n      for (let i = 0; i < facetCount; i++) {\n        const next = (i + 1) % facetCount;\n        const p1 = topPt;\n        const p2 = eqPoints[i];\n        const p3 = eqPoints[next];\n        const normal = computeNormal(p1, p2, p3);\n        drawFacet(p1, p2, p3, normal);\n      }\n\n      // Bottom Pyramid\n      for (let i = 0; i < facetCount; i++) {\n        const next = (i + 1) % facetCount;\n        const p1 = eqPoints[next];\n        const p2 = eqPoints[i];\n        const p3 = botPt;\n        const normal = computeNormal(p1, p2, p3);\n        drawFacet(p1, p2, p3, normal);\n      }\n\n      // Glaze pour flowing ripple line\n      if (pourY > topY + 6 && pourY < botY + 14) {\n        ctx.beginPath();\n        ctx.ellipse(cx, pourY, r * 0.9, 7, 0, 0, Math.PI * 2);\n        ctx.strokeStyle = accent;\n        ctx.lineWidth = 1.4;\n        ctx.stroke();\n      }\n\n      // Incident chiaroscuro beam\n      ctx.beginPath();\n      ctx.setLineDash([3, 4]);\n      ctx.moveTo(lx, ly);\n      ctx.lineTo(topPt.x, topPt.y);\n      ctx.strokeStyle = isDark ? "rgba(255, 255, 255, 0.14)" : "rgba(0, 0, 0, 0.14)";\n      ctx.lineWidth = 1;\n      ctx.stroke();\n      ctx.setLineDash([]);\n\n      // Light emitter pip\n      ctx.beginPath();\n      ctx.arc(lx, ly, 3.5, 0, Math.PI * 2);\n      ctx.fillStyle = accent;\n      ctx.fill();\n\n      animId = requestAnimationFrame(render);\n    };\n\n    animId = requestAnimationFrame(render);\n    return () => {\n      running = false;\n      cancelAnimationFrame(animId);\n    };\n  }, [size, progress, accent, isDark, isMobile, ptrX, ptrY]);\n\n  return (\n    <div\n      ref={containerRef}\n      onPointerMove={(e) => {\n        const r = e.currentTarget.getBoundingClientRect();\n        ptrX.set(e.clientX - r.left);\n        ptrY.set(e.clientY - r.top);\n      }}\n      onPointerLeave={() => {\n        ptrX.set(size.w * 0.38);\n        ptrY.set(size.h * 0.28);\n      }}\n      className="relative w-full h-full flex items-center justify-center cursor-crosshair select-none"\n      style={{ touchAction: "pan-y" }}\n    >\n      <canvas ref={canvasRef} className="w-full h-full object-contain pointer-events-none" />\n      <div className="absolute top-4 left-4 font-mono text-[10px] tracking-[0.2em] uppercase opacity-40 pointer-events-none">\n        Chiaroscuro ray / Facet normal\n      </div>\n    </div>\n  );\n}\n\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Detail: Cursor-lit Mirror Glaze Close-Up\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nfunction FacetDetail({ accent, isMobile }: { accent: string; isMobile: boolean }) {\n  const ref = useRef<HTMLDivElement>(null);\n  const x = useSpring(240, { stiffness: 220, damping: 28 });\n  const y = useSpring(180, { stiffness: 220, damping: 28 });\n\n  const center = () => {\n    const r = ref.current?.getBoundingClientRect();\n    if (!r) return;\n    x.set(r.width * 0.65);\n    y.set(r.height * 0.45);\n  };\n\n  useEffect(() => {\n    center();\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const mask = useMotionTemplate`radial-gradient(circle 200px at ${x}px ${y}px, #000 0%, transparent 100%)`;\n\n  return (\n    <div\n      ref={ref}\n      onPointerMove={(e) => {\n        const r = e.currentTarget.getBoundingClientRect();\n        x.set(e.clientX - r.left);\n        y.set(e.clientY - r.top);\n      }}\n      onPointerLeave={center}\n      className="relative overflow-hidden rounded-2xl border cursor-crosshair"\n      style={{\n        height: isMobile ? 360 : 460,\n        backgroundColor: "#0d0b09",\n        borderColor: "rgba(255,255,255,0.1)",\n        boxShadow: SPECULAR,\n        touchAction: "pan-y",\n      }}\n    >\n      <div className="absolute top-0 inset-x-0 h-px bg-gradient-to-r from-transparent via-white/30 to-transparent" />\n\n      {/* Base matte cacao surface */}\n      <div\n        className="absolute inset-0"\n        style={{\n          backgroundColor: "#120f0d",\n          backgroundImage:\n            "radial-gradient(circle at 1px 1px, rgba(255,255,255,0.06) 1px, transparent 0)",\n          backgroundSize: "20px 20px",\n        }}\n      />\n\n      {/* Lit mirror glaze layer with amber chiaroscuro refraction */}\n      <motion.div\n        className="absolute inset-0"\n        style={{\n          backgroundColor: "#080605",\n          backgroundImage: `linear-gradient(135deg, rgba(255,255,255,0.12) 0%, transparent 40%), linear-gradient(to right, ${accent}33 1px, transparent 1px), linear-gradient(to bottom, ${accent}33 1px, transparent 1px)`,\n          backgroundSize: "100% 100%, 48px 48px, 48px 48px",\n          maskImage: mask,\n          WebkitMaskImage: mask,\n        }}\n      />\n\n      <div className="relative z-10 h-full flex flex-col justify-end p-6 sm:p-10 pointer-events-none">\n        <h3\n          className={`font-black tracking-[-0.04em] leading-[1] text-white ${\n            isMobile ? "text-4xl" : "text-6xl"\n          }`}\n        >\n          Mirror glaze, up close.\n        </h3>\n        <p className="mt-3 max-w-sm text-sm leading-relaxed text-zinc-400">\n          Tempered at 29.4\xB0C to align cocoa butter crystals into a mirror sheen. Move over the facet\n          to inspect the reflection.\n        </p>\n      </div>\n    </div>\n  );\n}\n\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Choice: Edition Tilt Card\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nfunction EditionCard({\n  data,\n  active,\n  onSelect,\n  surface,\n  border,\n  muted,\n}: {\n  data: (typeof EDITIONS)[EditionKey];\n  active: boolean;\n  onSelect: () => void;\n  surface: string;\n  border: string;\n  muted: string;\n}) {\n  const rx = useSpring(0, TILT);\n  const ry = useSpring(0, TILT);\n  const gx = useMotionValue(50);\n  const gy = useMotionValue(50);\n  const glare = useMotionTemplate`radial-gradient(circle at ${gx}% ${gy}%, rgba(255,255,255,0.18), transparent 55%)`;\n\n  return (\n    <motion.button\n      type="button"\n      onClick={onSelect}\n      onPointerMove={(e) => {\n        const r = e.currentTarget.getBoundingClientRect();\n        const px = (e.clientX - r.left) / r.width;\n        const py = (e.clientY - r.top) / r.height;\n        ry.set((px - 0.5) * 12);\n        rx.set(-(py - 0.5) * 12);\n        gx.set(px * 100);\n        gy.set(py * 100);\n      }}\n      onPointerLeave={() => {\n        rx.set(0);\n        ry.set(0);\n        gx.set(50);\n        gy.set(50);\n      }}\n      whileHover={{ y: -4 }}\n      whileTap={{ scale: 0.96 }}\n      transition={SPRING}\n      style={{\n        rotateX: rx,\n        rotateY: ry,\n        transformPerspective: 900,\n        backgroundColor: surface,\n        borderColor: border,\n        boxShadow: SPECULAR,\n      }}\n      className="relative text-left rounded-2xl border p-5 cursor-pointer flex flex-col justify-between"\n    >\n      <div>\n        <div\n          className="relative h-36 rounded-xl overflow-hidden flex items-center justify-center"\n          style={{\n            backgroundColor: data.swatch,\n            backgroundImage:\n              "radial-gradient(circle at 1px 1px, rgba(255,255,255,0.08) 1px, transparent 0)",\n            backgroundSize: "16px 16px",\n          }}\n        >\n          <div\n            className="w-14 h-14 rounded-lg rotate-45 border"\n            style={{\n              borderColor: data.accent,\n              background: `linear-gradient(135deg, ${data.accent}44, transparent)`,\n            }}\n          />\n          <div\n            className="absolute right-4 inset-y-0 w-1"\n            style={{ backgroundColor: data.accent }}\n          />\n          <motion.div className="absolute inset-0" style={{ background: glare }} />\n        </div>\n\n        <div className="mt-4">\n          <div className="flex items-center justify-between">\n            <span className="text-base font-bold tracking-[-0.02em]">{data.name}</span>\n            <span className="font-mono text-xs tabular-nums text-zinc-400">{data.cacao}% cacao</span>\n          </div>\n          <p className="mt-1.5 text-xs leading-relaxed" style={{ color: muted }}>\n            {data.sub}\n          </p>\n        </div>\n      </div>\n\n      <div\n        className="mt-4 pt-3 border-t flex items-center justify-between text-xs font-mono"\n        style={{ borderColor: border }}\n      >\n        <span style={{ color: muted }}>Starting at</span>\n        <span className="font-bold tabular-nums text-sm">${data.price}</span>\n      </div>\n\n      {active && (\n        <motion.span\n          layoutId="edition-ring"\n          transition={SPRING}\n          className="absolute inset-0 rounded-2xl pointer-events-none"\n          style={{ border: `1.5px solid ${data.accent}` }}\n        />\n      )}\n    </motion.button>\n  );\n}\n\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Main Template Component\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nexport default function MonolithCacaoTemplate({\n  brandName = "MONOLITH CACAO",\n  theme = "dark",\n  deviceMode = "desktop",\n  heroTitle,\n  heroSubtitle,\n  hiddenSections,\n}: {\n  brandName?: string;\n  theme?: string;\n  deviceMode?: "desktop" | "tablet" | "mobile";\n  heroTitle?: string;\n  heroSubtitle?: string;\n  hiddenSections?: Record<string, boolean>;\n}) {\n  const config = { brandName, theme, heroTitle, heroSubtitle, hiddenSections };\n  const isDark = config.theme === "dark";\n  const reduce = useReducedMotion();\n\n  const rootRef = useRef<HTMLDivElement>(null);\n  const heroRef = useRef<HTMLElement>(null);\n  const trackRef = useRef<HTMLDivElement>(null);\n\n  const [containerWidth, setContainerWidth] = useState(1200);\n  useEffect(() => {\n    if (!rootRef.current) return;\n    const ro = new ResizeObserver((entries) => {\n      for (const entry of entries) setContainerWidth(entry.contentRect.width);\n    });\n    ro.observe(rootRef.current);\n    return () => ro.disconnect();\n  }, []);\n\n  const isMobile = deviceMode === "mobile" || containerWidth < 640;\n  const isTablet = deviceMode === "tablet" || (!isMobile && containerWidth < 1024);\n\n  const viewH = useViewHeight(rootRef);\n  const headerH = isMobile ? 64 : 80;\n  const heroH = Math.min(Math.max(viewH, 560), 880);\n  const trackH = viewH * 3.4;\n\n  /* Scroll-driven motions */\n  const rootP = useScrollProgress(rootRef, "track", viewH);\n  const rootSpring = useSpring(rootP, { stiffness: 200, damping: 34, mass: 0.4 });\n  const heroP = useScrollProgress(heroRef, "leave", viewH);\n  const heroSpring = useSpring(heroP, { stiffness: 120, damping: 28, mass: 0.4 });\n  const trackP = useScrollProgress(trackRef, "track", viewH);\n  const trackSpring = useSpring(trackP, { stiffness: 140, damping: 30, mass: 0.5 });\n\n  const headerBg = useTransform(rootP, [0, 0.015], ["rgba(8,8,10,0)", "rgba(8,8,10,0.85)"]);\n  const headerBorder = useTransform(\n    rootP,\n    [0, 0.015],\n    ["rgba(255,255,255,0)", "rgba(255,255,255,0.08)"]\n  );\n\n  const videoScale = useTransform(heroSpring, [0, 1], [1.08, 1.3]);\n  const videoFilter = useTransform(\n    heroSpring,\n    [0, 1],\n    ["blur(0px) brightness(1)", "blur(14px) brightness(0.35)"]\n  );\n  const titleY = useTransform(heroSpring, [0, 1], [0, -140]);\n  const titleOpacity = useTransform(heroSpring, [0, 0.55], [1, 0]);\n  const statsOpacity = useTransform(heroSpring, [0, 0.4], [1, 0]);\n\n  const px = useSpring(0, { stiffness: 80, damping: 22 });\n  const py = useSpring(0, { stiffness: 80, damping: 22 });\n  const titleX = useTransform(px, (v) => -v * 1.4);\n\n  /* Sticky Scene Phases */\n  const [activePhase, setActivePhase] = useState(0);\n  useMotionValueEvent(trackP, "change", (v) => {\n    setActivePhase(v < 0.4 ? 0 : v < 0.72 ? 1 : 2);\n  });\n\n  /* Selection state */\n  const [edition, setEdition] = useState<EditionKey>("criollo");\n  const [selectedWeight, setSelectedWeight] = useState<"340 g" | "680 g">("340 g");\n  const [reserved, setReserved] = useState(false);\n\n  const currentEdition = EDITIONS[edition];\n  const currentPhase = PHASES[activePhase];\n  const weight = WEIGHTS.find((w) => w.label === selectedWeight) || WEIGHTS[0];\n  const finalPrice = Math.round(currentEdition.price * weight.multiplier);\n\n  /* Neutrals & Single Accent */\n  const fg = isDark ? "#f4f4f5" : "#18181b";\n  const muted = isDark ? "#a1a1aa" : "#52525b";\n  const bg = isDark ? "#08080a" : "#faf8f5";\n  const surface = isDark ? "rgba(255, 255, 255, 0.03)" : "rgba(255, 255, 255, 0.9)";\n  const border = isDark ? "rgba(255, 255, 255, 0.08)" : "rgba(24, 24, 27, 0.08)";\n  const pill = isDark ? "rgba(255,255,255,0.08)" : "rgba(24,24,27,0.06)";\n\n  const brand = config.brandName || "Monolith Cacao";\n  const sectionPad = isMobile ? "px-5 py-20" : "px-10 py-32";\n\n  const go = (id: string) => {\n    rootRef.current\n      ?.querySelector(`#monolith-${id}`)\n      ?.scrollIntoView({ behavior: reduce ? "auto" : "smooth", block: "start" });\n  };\n\n  const handleReserve = () => {\n    setReserved(true);\n    setTimeout(() => setReserved(false), 2400);\n  };\n\n  return (\n    <div\n      ref={rootRef}\n      className="relative w-full overflow-x-clip font-sans selection:bg-white/20"\n      style={{ backgroundColor: bg, color: fg }}\n    >\n      {/* \u2500\u2500 1. Header (wordmark, 3 links, 1 action) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n      <motion.header\n        className="sticky top-0 z-40 flex items-center justify-between backdrop-blur-xl border-b"\n        style={{\n          height: headerH,\n          marginBottom: -headerH,\n          paddingInline: isMobile ? 20 : 40,\n          backgroundColor: headerBg,\n          borderBottomColor: headerBorder,\n        }}\n      >\n        <span className="text-sm font-bold tracking-[-0.02em] text-white">{brand}</span>\n\n        {!isMobile && (\n          <nav className="flex items-center gap-8 text-xs text-zinc-300">\n            {[\n              ["process", "Process"],\n              ["facet", "Surface"],\n              ["editions", "Editions"],\n            ].map(([id, label]) => (\n              <button\n                key={id}\n                type="button"\n                onClick={() => go(id)}\n                className="hover:text-white transition-colors cursor-pointer"\n              >\n                {label}\n              </button>\n            ))}\n          </nav>\n        )}\n\n        <motion.button\n          type="button"\n          onClick={() => go("order")}\n          whileTap={{ scale: 0.96 }}\n          transition={SPRING}\n          className="px-4 py-2 rounded-lg text-xs font-semibold bg-white text-zinc-950 cursor-pointer min-h-[44px]"\n        >\n          Reserve\n        </motion.button>\n\n        <motion.div\n          className="absolute bottom-0 inset-x-0 h-px origin-left"\n          style={{ scaleX: rootSpring, backgroundColor: currentEdition.accent }}\n        />\n      </motion.header>\n\n      {/* \u2500\u2500 2. Hero (full-bleed video + monumental typography + 3 stats) \u2500\u2500 */}\n      <section\n        ref={heroRef}\n        onPointerMove={(e) => {\n          if (reduce) return;\n          const r = e.currentTarget.getBoundingClientRect();\n          px.set(((e.clientX - r.left) / r.width - 0.5) * -18);\n          py.set(((e.clientY - r.top) / r.height - 0.5) * -12);\n        }}\n        className="relative w-full overflow-hidden flex flex-col"\n        style={{ height: heroH }}\n      >\n        <motion.video\n          src="/videos/monolith-cacao-glaze.mp4"\n          autoPlay\n          loop\n          muted\n          playsInline\n          preload="auto"\n          className="absolute inset-0 w-full h-full object-cover pointer-events-none"\n          style={{ scale: videoScale, filter: videoFilter, x: px, y: py }}\n        />\n\n        <div\n          className="absolute inset-0 pointer-events-none"\n          style={{\n            background:\n              "linear-gradient(to bottom, rgba(8,8,10,0.7) 0%, rgba(8,8,10,0.12) 35%, rgba(8,8,10,0.55) 72%, #08080a 100%)",\n          }}\n        />\n\n        <motion.div\n          className="relative z-10 flex-1 flex flex-col items-center justify-center text-center px-5"\n          style={{ y: titleY, x: titleX, opacity: titleOpacity }}\n        >\n          <h1\n            className={`font-black leading-[0.95] tracking-[-0.04em] text-white ${\n              isMobile ? "text-5xl" : isTablet ? "text-7xl" : "text-8xl"\n            }`}\n          >\n            <SplitWords text={config.heroTitle || "Carved from dark cacao."} delay={0.1} />\n          </h1>\n          <motion.p\n            initial={{ opacity: 0, y: 16 }}\n            animate={{ opacity: 1, y: 0 }}\n            transition={{ ...SPRING, delay: 0.55 }}\n            className={`mt-6 text-zinc-300 max-w-md ${isMobile ? "text-sm" : "text-base"}`}\n          >\n            {config.heroSubtitle ||\n              "Single-estate Venezuelan Criollo, tempered to a mirror finish. Three geometric cuts, zero additives."}\n          </motion.p>\n        </motion.div>\n\n        <motion.div\n          className="relative z-10 grid grid-cols-3 border-t"\n          style={{\n            opacity: statsOpacity,\n            borderColor: "rgba(255,255,255,0.12)",\n            marginInline: isMobile ? 20 : 40,\n            paddingTop: isMobile ? 20 : 24,\n            paddingBottom: isMobile ? 24 : 40,\n          }}\n        >\n          {[\n            { to: 85, suffix: "%", l: "Sur del Lago Criollo", dec: 0 },\n            { to: 72, suffix: " h", l: "Stone conched", dec: 0 },\n            { to: 29.4, suffix: "\xB0C", l: "Temper curve", dec: 1 },\n          ].map((s, i) => (\n            <div key={s.l}>\n              <div\n                className={`font-bold tracking-[-0.03em] text-white ${\n                  isMobile ? "text-base" : "text-3xl"\n                }`}\n              >\n                <Counter to={s.to} suffix={s.suffix} delay={0.8 + i * 0.12} decimals={s.dec} />\n              </div>\n              <div className="font-mono text-[10px] tracking-[0.2em] uppercase text-zinc-400 mt-1">\n                {s.l}\n              </div>\n            </div>\n          ))}\n        </motion.div>\n      </section>\n\n      {/* \u2500\u2500 3. Scene: Glaze Pour & Chiaroscuro Specular Raytracing \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n      {!config.hiddenSections?.process && (\n        <div id="monolith-process" ref={trackRef} style={{ height: trackH }} className="relative">\n        <div\n          className="sticky top-0 overflow-hidden flex flex-col justify-center"\n          style={{ height: viewH, paddingTop: headerH }}\n        >\n          <div\n            className={`max-w-6xl mx-auto w-full h-full flex flex-col justify-center ${\n              isMobile ? "px-5 py-6" : "px-10 py-10"\n            }`}\n          >\n            <div\n              className={`grid items-center h-full gap-8 ${\n                isMobile ? "grid-cols-1" : isTablet ? "grid-cols-2" : "grid-cols-12"\n              }`}\n            >\n              {/* Visual Stage */}\n              <div\n                className={`h-full min-h-[300px] flex items-center justify-center ${\n                  isMobile ? "order-1 h-[260px]" : isTablet ? "order-1" : "col-span-7"\n                }`}\n              >\n                <GlazeStage\n                  progress={trackSpring}\n                  accent={currentEdition.accent}\n                  isDark={isDark}\n                  isMobile={isMobile}\n                />\n              </div>\n\n              {/* Phase Copy */}\n              <div\n                className={`flex flex-col justify-center ${\n                  isMobile ? "order-2" : isTablet ? "order-2" : "col-span-5"\n                }`}\n              >\n                <AnimatePresence mode="wait">\n                  <motion.div\n                    key={activePhase}\n                    initial={{ opacity: 0, y: 16 }}\n                    animate={{ opacity: 1, y: 0 }}\n                    exit={{ opacity: 0, y: -16 }}\n                    transition={SPRING}\n                    className="space-y-4"\n                  >\n                    <h2\n                      className={`font-black tracking-[-0.03em] leading-[1.05] ${\n                        isMobile ? "text-2xl" : "text-4xl"\n                      }`}\n                    >\n                      {currentPhase.title}\n                    </h2>\n                    <p className="text-sm leading-relaxed" style={{ color: muted }}>\n                      {currentPhase.body}\n                    </p>\n\n                    <div className="pt-4 border-t" style={{ borderColor: border }}>\n                      <div\n                        className="text-2xl font-bold tracking-tight"\n                        style={{ color: currentEdition.accent }}\n                      >\n                        {currentPhase.figure}\n                        {currentPhase.unit}\n                      </div>\n                      <div className="font-mono text-[10px] tracking-[0.2em] uppercase text-zinc-400 mt-0.5">\n                        {currentPhase.caption}\n                      </div>\n                    </div>\n                  </motion.div>\n                </AnimatePresence>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n      )}\n\n      {/* \u2500\u2500 4. Detail: Cursor-lit Mirror Glaze Close-Up \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n      {!config.hiddenSections?.facet && (\n        <section id="monolith-facet" className={`max-w-6xl mx-auto w-full ${sectionPad}`}>\n          <Reveal>\n            <FacetDetail accent={currentEdition.accent} isMobile={isMobile} />\n          </Reveal>\n        </section>\n      )}\n\n      {/* \u2500\u2500 5. Choice: Three Geometric Cuts (Tilt Cards + Weight) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n      {!config.hiddenSections?.editions && (\n        <section id="monolith-editions" className={`max-w-6xl mx-auto w-full ${sectionPad}`}>\n          <Reveal>\n            <div className="max-w-md">\n              <h2\n                className={`font-black tracking-[-0.04em] leading-[1] ${\n                  isMobile ? "text-3xl" : "text-5xl"\n                }`}\n              >\n                Three geometric cuts.\n              </h2>\n              <p className="mt-3 text-sm leading-relaxed" style={{ color: muted }}>\n                Each single-origin bar is poured to order into CNC-milled basalt forms.\n              </p>\n            </div>\n          </Reveal>\n\n          <div\n            className={`mt-10 grid gap-4 ${\n              isMobile ? "grid-cols-1" : isTablet ? "grid-cols-2" : "grid-cols-3"\n            }`}\n          >\n            {(["criollo", "gianduja", "espresso"] as const).map((key) => (\n              <EditionCard\n                key={key}\n                data={EDITIONS[key]}\n                active={edition === key}\n                onSelect={() => setEdition(key)}\n                surface={surface}\n                border={border}\n                muted={muted}\n              />\n            ))}\n          </div>\n\n          {/* Weight Selector */}\n          <div className="mt-8 flex items-center justify-between flex-wrap gap-4 pt-6 border-t" style={{ borderColor: border }}>\n            <div className="font-mono text-xs text-zinc-400 uppercase tracking-wider">\n              Format & Serving\n            </div>\n            <div className="flex items-center gap-2">\n              {WEIGHTS.map((w) => {\n                const isSelected = selectedWeight === w.label;\n                return (\n                  <button\n                    key={w.label}\n                    type="button"\n                    onClick={() => setSelectedWeight(w.label as any)}\n                    className="relative px-4 py-2 rounded-lg text-xs font-mono font-semibold transition-colors cursor-pointer min-h-[44px]"\n                    style={{ color: isSelected ? fg : muted }}\n                  >\n                    {isSelected && (\n                      <motion.span\n                        layoutId="weight-pill"\n                        transition={SPRING}\n                        className="absolute inset-0 rounded-lg pointer-events-none"\n                        style={{ backgroundColor: pill }}\n                      />\n                    )}\n                    <span className="relative z-10">{w.label}</span>\n                  </button>\n                );\n              })}\n            </div>\n          </div>\n        </section>\n      )}\n\n      {/* \u2500\u2500 6. Action: Order Card & Magnetic Button \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n      {!config.hiddenSections?.order && (\n        <section id="monolith-order" className={`max-w-6xl mx-auto w-full ${sectionPad}`}>\n          <Reveal>\n            <div\n              className="p-6 sm:p-10 rounded-3xl border relative overflow-hidden"\n              style={{\n                backgroundColor: surface,\n                borderColor: border,\n                boxShadow: SPECULAR,\n              }}\n            >\n              <div className="absolute top-0 inset-x-0 h-px bg-gradient-to-r from-transparent via-white/30 to-transparent" />\n              <div className="flex flex-col md:flex-row md:items-center justify-between gap-8">\n                <div className="space-y-3">\n                  <h3 className="text-2xl sm:text-3xl font-black tracking-[-0.03em]">\n                    Reserve a monolith.\n                  </h3>\n                  <p className="text-sm leading-relaxed max-w-md" style={{ color: muted }}>\n                    {currentEdition.name} ({weight.label}). Single-estate Venezuelan Criollo,\n                    tempered to order and packed in temperature-controlled packaging.\n                  </p>\n                  <div className="font-mono text-xs text-zinc-400">\n                    Dispatched within 48 hours. Climate-controlled delivery.\n                  </div>\n                </div>\n\n                <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-5 shrink-0">\n                  <div className="text-left sm:text-right">\n                    <div className="text-3xl font-black tabular-nums tracking-[-0.03em]">\n                      ${finalPrice}\n                    </div>\n                    <div className="text-[10px] font-mono tracking-widest uppercase text-zinc-400 mt-0.5">\n                      {weight.serves}\n                    </div>\n                  </div>\n\n                  <MagneticButton\n                    onClick={handleReserve}\n                    className="px-8 py-4 rounded-xl text-xs font-bold bg-white text-zinc-950 cursor-pointer shadow-lg min-h-[44px]"\n                  >\n                    <AnimatePresence mode="wait">\n                      {reserved ? (\n                        <motion.span\n                          key="reserved"\n                          initial={{ opacity: 0, y: 6 }}\n                          animate={{ opacity: 1, y: 0 }}\n                          exit={{ opacity: 0, y: -6 }}\n                          transition={SPRING}\n                          className="flex items-center gap-2"\n                        >\n                          <Check className="w-4 h-4" />\n                          <span>Added to Order</span>\n                        </motion.span>\n                      ) : (\n                        <motion.span\n                          key="idle"\n                          initial={{ opacity: 0, y: 6 }}\n                          animate={{ opacity: 1, y: 0 }}\n                          exit={{ opacity: 0, y: -6 }}\n                          transition={SPRING}\n                          className="flex items-center gap-2"\n                        >\n                          <span>Reserve Monolith</span>\n                          <ArrowRight className="w-3.5 h-3.5" />\n                        </motion.span>\n                      )}\n                    </AnimatePresence>\n                  </MagneticButton>\n                </div>\n              </div>\n            </div>\n          </Reveal>\n        </section>\n      )}\n\n      {/* \u2500\u2500 7. Footer: One line \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n      <footer\n        className="border-t py-8 px-5 sm:px-10 text-center text-xs font-mono"\n        style={{ borderColor: border, color: muted }}\n      >\n        <p>\xA9 2026 Monolith Cacao. Single-estate dark chocolate.</p>\n      </footer>\n    </div>\n  );\n}\n'
};

// src/registry/template-amarena-royale-pro.ts
var templateAmarenaRoyalePro = {
  name: "template-amarena-royale-pro",
  dependencies: ["framer-motion", "lucide-react"],
  fileName: "template-amarena-royale-pro.tsx",
  content: '"use client";\n\nimport React, { useEffect, useRef, useState, RefObject } from "react";\nimport {\n  motion,\n  AnimatePresence,\n  animate,\n  useInView,\n  useMotionTemplate,\n  useMotionValue,\n  useReducedMotion,\n  useSpring,\n  useTransform,\n} from "framer-motion";\nimport { ArrowRight, Check } from "lucide-react";\n\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Constants & Motion Tokens\n   \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nconst SPRING = { type: "spring", stiffness: 400, damping: 30, mass: 0.8 } as const;\nconst TILT = { stiffness: 260, damping: 24, mass: 0.6 } as const;\n\ntype EditionKey = "royale" | "chantilly" | "noir";\n\ninterface Edition {\n  id: EditionKey;\n  name: string;\n  tagline: string;\n  cacao: string;\n  accentDark: string;\n  accentLight: string;\n  notes: string;\n  priceFour: number;\n  priceEight: number;\n}\n\nconst EDITIONS: Record<EditionKey, Edition> = {\n  royale: {\n    id: "royale",\n    name: "Amarena Royale",\n    tagline: "Wild stone-fruit reduction, 70% dark sponge, Bourbon chantilly.",\n    cacao: "70% Sur del Lago",\n    accentDark: "#fb7185",\n    accentLight: "#be123c",\n    notes: "Wild Emilia-Romagna cherries slow-steeped for 96 hours, paired with single-origin Venezuelan chocolate and hand-laid gold flakes.",\n    priceFour: 48,\n    priceEight: 88,\n  },\n  chantilly: {\n    id: "chantilly",\n    name: "Chantilly d\'Or",\n    tagline: "Double-whipped mascarpone, bean caviar, fleur de sel caramel.",\n    cacao: "66% Grand Cru",\n    accentDark: "#fbbf24",\n    accentLight: "#b45309",\n    notes: "Madagascar bourbon vanilla caviar folded into chilled Normandie cream over a crisp hazelnut sabl\xE9 base.",\n    priceFour: 46,\n    priceEight: 84,\n  },\n  noir: {\n    id: "noir",\n    name: "Noir Absolu",\n    tagline: "Single-estate 80% ganache, tart griotte coulis, smoked sea salt.",\n    cacao: "80% Sur del Lago",\n    accentDark: "#f43f5e",\n    accentLight: "#9f1239",\n    notes: "Unsweetened dark chocolate conche with high fruit acidity, balanced by tart wild cherries and mineral flake salt.",\n    priceFour: 52,\n    priceEight: 96,\n  },\n};\n\nconst STATS = [\n  { figure: 70, suffix: "%", label: "Sur del Lago cacao" },\n  { figure: 96, suffix: "h", label: "Cherry maceration" },\n  { figure: 4, suffix: "\xB0C", label: "Serving temperature" },\n] as const;\n\nconst ANATOMY = [\n  {\n    title: "Crisp 70% shell",\n    detail: "Hand-tempered chocolate dome with an audible snap. Finished with a high-gloss glaze.",\n    metric: "31.5\xB0C",\n    caption: "Temper set",\n  },\n  {\n    title: "Bourbon chantilly",\n    detail: "Double-emulsified mascarpone whipped with scraped Madagascar vanilla pods.",\n    metric: "38%",\n    caption: "Butterfat density",\n  },\n  {\n    title: "Molten cherry core",\n    detail: "Whole wild amarena cherries reduced in their natural ruby syrup.",\n    metric: "64\xB0",\n    caption: "Brix concentration",\n  },\n] as const;\n\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Scroll Helpers (Modal-safe scroller detection)\n   \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nfunction findScroller(el: HTMLElement | null): HTMLElement | null {\n  let p = el?.parentElement ?? null;\n  while (p) {\n    const o = getComputedStyle(p).overflowY;\n    if (o === "auto" || o === "scroll") return p;\n    p = p.parentElement;\n  }\n  return null;\n}\n\nfunction useScrollProgress(\n  ref: RefObject<HTMLElement | null>,\n  kind: "leave" | "track"\n) {\n  const mv = useMotionValue(0);\n  useEffect(() => {\n    const el = ref.current;\n    if (!el) return;\n    const scroller = findScroller(el);\n    const update = () => {\n      const r = el.getBoundingClientRect();\n      const top = scroller ? scroller.getBoundingClientRect().top : 0;\n      const vh = scroller ? scroller.clientHeight : window.innerHeight;\n      const rel = r.top - top;\n      const total = kind === "track" ? r.height - vh : r.height;\n      mv.set(total > 0 ? Math.min(1, Math.max(0, -rel / total)) : 0);\n    };\n    update();\n    const target: HTMLElement | Window = scroller ?? window;\n    target.addEventListener("scroll", update, { passive: true });\n    window.addEventListener("resize", update);\n    return () => {\n      target.removeEventListener("scroll", update);\n      window.removeEventListener("resize", update);\n    };\n  }, [ref, kind, mv]);\n  return mv;\n}\n\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Micro-components\n   \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nfunction SplitWords({\n  text,\n  className,\n  delay = 0,\n  onView = false,\n}: {\n  text: string;\n  className?: string;\n  delay?: number;\n  onView?: boolean;\n}) {\n  const words = text.split(" ");\n  return (\n    <span className={className} aria-label={text}>\n      {words.map((w, i) => (\n        <span\n          key={i}\n          aria-hidden\n          className="inline-block overflow-hidden align-bottom pb-[0.14em] -mb-[0.14em]"\n        >\n          <motion.span\n            className="inline-block"\n            initial={{ y: "115%" }}\n            {...(onView\n              ? { whileInView: { y: 0 }, viewport: { once: true, margin: "-10% 0px" } }\n              : { animate: { y: 0 } })}\n            transition={{ ...SPRING, delay: delay + i * 0.07 }}\n          >\n            {w}\n          </motion.span>\n          {i < words.length - 1 ? "\\u00A0" : ""}\n        </span>\n      ))}\n    </span>\n  );\n}\n\nfunction Counter({\n  to,\n  suffix = "",\n  delay = 0,\n  duration = 1.6,\n}: {\n  to: number;\n  suffix?: string;\n  delay?: number;\n  duration?: number;\n}) {\n  const ref = useRef<HTMLSpanElement>(null);\n  const inView = useInView(ref, { once: true });\n  const reduce = useReducedMotion();\n  const [v, setV] = useState(0);\n\n  useEffect(() => {\n    if (!inView) return;\n    const c = animate(0, to, {\n      duration: reduce ? 0 : duration,\n      delay: reduce ? 0 : delay,\n      ease: [0.16, 1, 0.3, 1],\n      onUpdate: (val) => setV(val),\n    });\n    return () => c.stop();\n  }, [inView, to, delay, duration, reduce]);\n\n  return (\n    <span ref={ref} className="tabular-nums">\n      {Math.round(v).toLocaleString("en-US")}\n      {suffix}\n    </span>\n  );\n}\n\nfunction MagneticButton({\n  children,\n  onClick,\n  className,\n  style,\n}: {\n  children: React.ReactNode;\n  onClick: () => void;\n  className?: string;\n  style?: React.CSSProperties;\n}) {\n  const x = useSpring(0, { stiffness: 300, damping: 20, mass: 0.5 });\n  const y = useSpring(0, { stiffness: 300, damping: 20, mass: 0.5 });\n  return (\n    <motion.button\n      type="button"\n      onClick={onClick}\n      onPointerMove={(e) => {\n        const r = e.currentTarget.getBoundingClientRect();\n        x.set((e.clientX - (r.left + r.width / 2)) * 0.12);\n        y.set((e.clientY - (r.top + r.height / 2)) * 0.35);\n      }}\n      onPointerLeave={() => {\n        x.set(0);\n        y.set(0);\n      }}\n      whileTap={{ scale: 0.96 }}\n      transition={SPRING}\n      style={{ x, y, ...style }}\n      className={className}\n    >\n      {children}\n    </motion.button>\n  );\n}\n\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   SIGNATURE WOW MOMENT: Spring-Damped Cleave (Cross-Section Split Inspector)\n   \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nfunction CleaveInspector({\n  isDark,\n  accent,\n  isMobile,\n  isTablet,\n}: {\n  isDark: boolean;\n  accent: string;\n  isMobile: boolean;\n  isTablet: boolean;\n}) {\n  const [split, setSplit] = useState(0.5);\n  const splitSpring = useSpring(0.5, SPRING);\n  const containerRef = useRef<HTMLDivElement>(null);\n  const isDragging = useRef(false);\n\n  const updateSplitFromClientX = (clientX: number) => {\n    if (!containerRef.current) return;\n    const r = containerRef.current.getBoundingClientRect();\n    const pct = Math.min(0.96, Math.max(0.04, (clientX - r.left) / r.width));\n    setSplit(pct);\n    splitSpring.set(pct);\n  };\n\n  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {\n    isDragging.current = true;\n    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);\n    updateSplitFromClientX(e.clientX);\n  };\n\n  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {\n    if (!isDragging.current) return;\n    updateSplitFromClientX(e.clientX);\n  };\n\n  const handlePointerUp = (e: React.PointerEvent<HTMLDivElement>) => {\n    isDragging.current = false;\n    try {\n      (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId);\n    } catch {}\n  };\n\n  const setPreset = (target: number) => {\n    setSplit(target);\n    splitSpring.set(target);\n  };\n\n  const splitPct = useTransform(splitSpring, (v) => `${(v * 100).toFixed(2)}%`);\n  const leftClip = useTransform(splitSpring, (v) => `inset(0 ${(100 - v * 100).toFixed(2)}% 0 0)`);\n  const rightClip = useTransform(splitSpring, (v) => `inset(0 0 0 ${(v * 100).toFixed(2)}%)`);\n\n  return (\n    <div className={isMobile ? "space-y-3" : "space-y-6"}>\n      {/* Interactive Lens Viewport */}\n      <div\n        ref={containerRef}\n        onPointerDown={handlePointerDown}\n        onPointerMove={handlePointerMove}\n        onPointerUp={handlePointerUp}\n        className={`relative w-full overflow-hidden select-none cursor-ew-resize border touch-none ${\n          isMobile\n            ? "aspect-[4/3] rounded-xl"\n            : isTablet\n            ? "aspect-[16/11] rounded-2xl"\n            : "aspect-[16/9] rounded-2xl"\n        }`}\n        style={{\n          borderColor: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.08)",\n          boxShadow: isDark\n            ? "inset 0 1px 0 0 rgba(255,255,255,0.12), 0 8px 32px -4px rgba(0,0,0,0.5)"\n            : "inset 0 1px 0 0 rgba(255,255,255,0.8), 0 8px 24px -4px rgba(0,0,0,0.06)",\n        }}\n      >\n        {/* Top specular ray */}\n        <div className="absolute top-0 inset-x-0 h-px bg-gradient-to-r from-transparent via-white/25 to-transparent z-30 pointer-events-none" />\n\n        {/* \u2500\u2500\u2500 LEFT: Exterior Glazed Dome \u2500\u2500\u2500 */}\n        <motion.div\n          className="absolute inset-0 z-10 flex items-center justify-center overflow-hidden"\n          style={{\n            clipPath: leftClip,\n            backgroundColor: isDark ? "#0c080a" : "#f5edea",\n          }}\n        >\n          {/* Subtle texture grid */}\n          <div\n            className="absolute inset-0 pointer-events-none opacity-20"\n            style={{\n              backgroundImage: isDark\n                ? "radial-gradient(circle at 1px 1px, rgba(255,255,255,0.15) 1px, transparent 0)"\n                : "radial-gradient(circle at 1px 1px, rgba(0,0,0,0.15) 1px, transparent 0)",\n              backgroundSize: "24px 24px",\n            }}\n          />\n\n          {/* Exterior Artwork Simulation */}\n          <div\n            className={`relative rounded-full flex items-center justify-center ${\n              isMobile\n                ? "w-40 h-40"\n                : isTablet\n                ? "w-56 h-56"\n                : "w-72 h-72"\n            }`}\n          >\n            {/* Ambient Shadow */}\n            <div className="absolute inset-0 rounded-full bg-black/40 blur-xl transform translate-y-3" />\n\n            {/* Tempered Chocolate Dome */}\n            <div\n              className={`relative rounded-full overflow-hidden border ${\n                isMobile\n                  ? "w-32 h-32"\n                  : isTablet\n                  ? "w-44 h-44"\n                  : "w-60 h-60"\n              }`}\n              style={{\n                background: isDark\n                  ? "radial-gradient(circle at 35% 30%, #2a1118 0%, #17070b 55%, #080305 100%)"\n                  : "radial-gradient(circle at 35% 30%, #471e28 0%, #260c13 55%, #150508 100%)",\n                borderColor: isDark ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.15)",\n                boxShadow: "inset -8px -12px 28px rgba(0,0,0,0.8), inset 6px 8px 18px rgba(255,255,255,0.18)",\n              }}\n            >\n              {/* Specular Ray on Dome */}\n              <div\n                className="absolute top-3 left-4 sm:top-6 sm:left-8 w-14 sm:w-20 h-6 sm:h-10 rounded-full transform -rotate-25 blur-sm pointer-events-none"\n                style={{ background: "rgba(255, 255, 255, 0.22)" }}\n              />\n\n              {/* Hand-laid 24K Gold Leaf Flecks */}\n              <div\n                className="absolute top-8 right-8 w-2 h-1.5 rotate-12 rounded-sm"\n                style={{ backgroundColor: "#fbbf24", boxShadow: "0 0 8px rgba(251,191,36,0.6)" }}\n              />\n              <div\n                className="absolute top-14 right-12 w-1.5 h-1 -rotate-45 rounded-sm"\n                style={{ backgroundColor: "#fef08a", boxShadow: "0 0 6px rgba(254,240,138,0.7)" }}\n              />\n              <div\n                className="absolute bottom-10 left-10 w-2 h-1 rotate-35 rounded-sm"\n                style={{ backgroundColor: "#f59e0b", boxShadow: "0 0 6px rgba(245,158,11,0.5)" }}\n              />\n\n              {/* Crown Candied Cherry */}\n              <div\n                className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full border ${\n                  isMobile ? "w-9 h-9" : isTablet ? "w-14 h-14" : "w-18 h-18"\n                }`}\n                style={{\n                  background: "radial-gradient(circle at 35% 32%, #e11d48 0%, #881337 55%, #4c0519 100%)",\n                  borderColor: "rgba(255,255,255,0.2)",\n                  boxShadow: "0 12px 24px rgba(0,0,0,0.6), inset 2px 3px 6px rgba(255,255,255,0.35)",\n                }}\n              >\n                <div className="absolute top-1 left-2 w-3 h-1.5 rounded-full bg-white/40 -rotate-20" />\n              </div>\n            </div>\n          </div>\n\n          {/* Corner Caption */}\n          <div className="absolute top-2.5 left-2.5 sm:top-4 sm:left-4 z-20 pointer-events-none">\n            <span\n              className="font-mono text-[9px] tracking-[0.2em] uppercase px-2 py-0.5 rounded border backdrop-blur-md"\n              style={{\n                backgroundColor: isDark ? "rgba(0,0,0,0.6)" : "rgba(255,255,255,0.75)",\n                borderColor: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.08)",\n                color: isDark ? "#f4f4f5" : "#18181b",\n              }}\n            >\n              Exterior Shell\n            </span>\n          </div>\n        </motion.div>\n\n        {/* \u2500\u2500\u2500 RIGHT: Interior Cross-Section \u2500\u2500\u2500 */}\n        <motion.div\n          className="absolute inset-0 z-10 flex items-center justify-center overflow-hidden"\n          style={{\n            clipPath: rightClip,\n            backgroundColor: isDark ? "#080608" : "#f1e8e5",\n          }}\n        >\n          {/* Subtle texture grid */}\n          <div\n            className="absolute inset-0 pointer-events-none opacity-20"\n            style={{\n              backgroundImage: isDark\n                ? "radial-gradient(circle at 1px 1px, rgba(255,255,255,0.15) 1px, transparent 0)"\n                : "radial-gradient(circle at 1px 1px, rgba(0,0,0,0.15) 1px, transparent 0)",\n              backgroundSize: "24px 24px",\n            }}\n          />\n\n          {/* Cross-section Artwork */}\n          <div\n            className={`relative rounded-full flex items-center justify-center ${\n              isMobile\n                ? "w-40 h-40"\n                : isTablet\n                ? "w-56 h-56"\n                : "w-72 h-72"\n            }`}\n          >\n            {/* Ambient Shadow */}\n            <div className="absolute inset-0 rounded-full bg-black/40 blur-xl transform translate-y-3" />\n\n            {/* Cleaved Hemisphere Cross-section */}\n            <div\n              className={`relative rounded-full overflow-hidden border p-2 flex flex-col justify-end ${\n                isMobile\n                  ? "w-32 h-32"\n                  : isTablet\n                  ? "w-44 h-44"\n                  : "w-60 h-60"\n              }`}\n              style={{\n                backgroundColor: isDark ? "#170a0e" : "#32161e",\n                borderColor: isDark ? "rgba(255,255,255,0.12)" : "rgba(0,0,0,0.15)",\n                boxShadow: "inset 0 0 32px rgba(0,0,0,0.85)",\n              }}\n            >\n              {/* Outer Shell Ring */}\n              <div\n                className="absolute inset-0 rounded-full border-2 sm:border-3 pointer-events-none"\n                style={{ borderColor: "#1e0b11" }}\n              />\n\n              {/* Layer 1: Aerated Sponge Base */}\n              <div\n                className={`relative w-full rounded-b-full border-t flex items-center justify-center overflow-hidden ${\n                  isMobile ? "h-12" : isTablet ? "h-16" : "h-20"\n                }`}\n                style={{\n                  backgroundColor: isDark ? "#261319" : "#42222a",\n                  borderColor: "rgba(255,255,255,0.08)",\n                  backgroundImage:\n                    "radial-gradient(circle at 2px 2px, rgba(0,0,0,0.35) 1.5px, transparent 0)",\n                  backgroundSize: "8px 8px",\n                }}\n              >\n                <span className="font-mono text-[8px] uppercase tracking-widest text-zinc-400 opacity-70">\n                  Micro-sponge\n                </span>\n              </div>\n\n              {/* Layer 2: Folded Bourbon Chantilly */}\n              <div\n                className={`relative w-full border-t flex items-center justify-center ${\n                  isMobile ? "h-10" : isTablet ? "h-14" : "h-18"\n                }`}\n                style={{\n                  backgroundColor: isDark ? "#f5edd6" : "#fef8ee",\n                  borderColor: "rgba(0,0,0,0.15)",\n                  color: "#1c1917",\n                }}\n              >\n                <div\n                  className="absolute inset-0 opacity-40 pointer-events-none"\n                  style={{\n                    backgroundImage:\n                      "radial-gradient(circle at 1px 1px, #78350f 1px, transparent 0)",\n                    backgroundSize: "12px 12px",\n                  }}\n                />\n                <span className="relative font-mono text-[8px] uppercase tracking-widest text-stone-700 font-semibold">\n                  Chantilly\n                </span>\n              </div>\n\n              {/* Layer 3: Central Molten Wild Amarena Core */}\n              <div\n                className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full border flex items-center justify-center ${\n                  isMobile ? "w-12 h-12" : isTablet ? "w-16 h-16" : "w-20 h-20"\n                }`}\n                style={{\n                  background: "radial-gradient(circle at 40% 35%, #e11d48 0%, #9f1239 60%, #4c0519 100%)",\n                  borderColor: "rgba(255,255,255,0.25)",\n                  boxShadow: "0 0 24px rgba(225,29,72,0.45), inset 0 2px 8px rgba(255,255,255,0.3)",\n                }}\n              >\n                <span className="font-mono text-[7px] sm:text-[8px] uppercase tracking-widest text-white/90 text-center px-1 font-bold">\n                  Molten Core\n                </span>\n              </div>\n            </div>\n          </div>\n\n          {/* Corner Caption */}\n          <div className="absolute top-2.5 right-2.5 sm:top-4 sm:right-4 z-20 pointer-events-none">\n            <span\n              className="font-mono text-[9px] tracking-[0.2em] uppercase px-2 py-0.5 rounded border backdrop-blur-md"\n              style={{\n                backgroundColor: isDark ? "rgba(0,0,0,0.6)" : "rgba(255,255,255,0.75)",\n                borderColor: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.08)",\n                color: isDark ? "#f4f4f5" : "#18181b",\n              }}\n            >\n              Interior Cleave\n            </span>\n          </div>\n        </motion.div>\n\n        {/* \u2500\u2500\u2500 Drag Line & Handle \u2500\u2500\u2500 */}\n        <motion.div\n          className="absolute top-0 bottom-0 z-20 w-0.5 pointer-events-none"\n          style={{\n            left: splitPct,\n            backgroundColor: accent,\n            boxShadow: `0 0 12px ${accent}`,\n          }}\n        >\n          {/* Central Circular Knob */}\n          <div\n            className={`absolute top-1/2 -translate-y-1/2 -translate-x-1/2 rounded-full border flex items-center justify-center backdrop-blur-xl shadow-lg transition-transform hover:scale-105 ${\n              isMobile ? "w-7 h-7" : "w-9 h-9"\n            }`}\n            style={{\n              backgroundColor: isDark ? "rgba(12, 8, 10, 0.92)" : "rgba(255, 255, 255, 0.95)",\n              borderColor: accent,\n            }}\n          >\n            <div className="flex items-center gap-0.5 sm:gap-1">\n              <div className="w-0.5 sm:w-1 h-2.5 sm:h-3 rounded-full" style={{ backgroundColor: accent }} />\n              <div className="w-0.5 sm:w-1 h-2.5 sm:h-3 rounded-full opacity-40" style={{ backgroundColor: accent }} />\n            </div>\n          </div>\n        </motion.div>\n      </div>\n\n      {/* Preset Controls */}\n      <div className="flex flex-wrap items-center justify-between gap-2 pt-1">\n        <div\n          className="flex items-center gap-1 p-0.5 sm:p-1 rounded-lg sm:rounded-xl border"\n          style={{\n            backgroundColor: isDark ? "rgba(255,255,255,0.02)" : "rgba(0,0,0,0.02)",\n            borderColor: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.06)",\n          }}\n        >\n          {[\n            { label: "Glaze Shell", val: 0.1 },\n            { label: "Even Split", val: 0.5 },\n            { label: "Molten Core", val: 0.9 },\n          ].map((preset) => {\n            const active = Math.abs(split - preset.val) < 0.15;\n            return (\n              <button\n                key={preset.label}\n                type="button"\n                onClick={() => setPreset(preset.val)}\n                className={`relative rounded-md sm:rounded-lg font-medium transition-colors cursor-pointer ${\n                  isMobile ? "px-2 py-1 text-[10px]" : "px-3 py-1.5 text-xs"\n                }`}\n                style={{\n                  color: active\n                    ? isDark ? "#ffffff" : "#09090b"\n                    : isDark ? "#a1a1aa" : "#71717a",\n                }}\n              >\n                {active && (\n                  <motion.span\n                    layoutId="cleave-preset-pill"\n                    transition={SPRING}\n                    className="absolute inset-0 rounded-md sm:rounded-lg"\n                    style={{\n                      backgroundColor: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.06)",\n                    }}\n                  />\n                )}\n                <span className="relative z-10">{preset.label}</span>\n              </button>\n            );\n          })}\n        </div>\n\n        {!isMobile && (\n          <p className="font-mono text-[11px] text-zinc-500">\n            Drag divider to inspect interior aeration.\n          </p>\n        )}\n      </div>\n\n      {/* 3 Physical Strata Callouts */}\n      <div className={`grid pt-2 ${isMobile ? "grid-cols-1 gap-2" : isTablet ? "grid-cols-3 gap-3" : "grid-cols-3 gap-4"}`}>\n        {ANATOMY.map((item) => (\n          <div\n            key={item.title}\n            className={`rounded-xl border relative ${\n              isMobile ? "p-3 space-y-1" : "p-4 space-y-1.5"\n            }`}\n            style={{\n              backgroundColor: isDark ? "rgba(255,255,255,0.02)" : "rgba(0,0,0,0.02)",\n              borderColor: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.06)",\n            }}\n          >\n            <div className="flex items-center justify-between">\n              <span className="font-mono text-xs font-bold" style={{ color: accent }}>\n                {item.metric}\n              </span>\n              <span className="font-mono text-[9px] text-zinc-500 uppercase tracking-wider">\n                {item.caption}\n              </span>\n            </div>\n            <h3\n              className="text-xs font-semibold tracking-tight"\n              style={{ color: isDark ? "#f4f4f5" : "#18181b" }}\n            >\n              {item.title}\n            </h3>\n            <p className="text-[11px] text-zinc-400 leading-relaxed">\n              {item.detail}\n            </p>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   CURSOR-LIT MATERIAL INSPECTOR\n   \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nfunction CursorLitMaterial({\n  isDark,\n  accent,\n  isMobile,\n}: {\n  isDark: boolean;\n  accent: string;\n  isMobile: boolean;\n}) {\n  const cardRef = useRef<HTMLDivElement>(null);\n  const x = useSpring(240, { stiffness: 220, damping: 28 });\n  const y = useSpring(140, { stiffness: 220, damping: 28 });\n\n  const mask = useMotionTemplate`radial-gradient(circle 200px at ${x}px ${y}px, #000 0%, transparent 100%)`;\n\n  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {\n    if (!cardRef.current) return;\n    const r = cardRef.current.getBoundingClientRect();\n    x.set(e.clientX - r.left);\n    y.set(e.clientY - r.top);\n  };\n\n  const handlePointerLeave = () => {\n    if (!cardRef.current) return;\n    const r = cardRef.current.getBoundingClientRect();\n    x.set(r.width / 2);\n    y.set(r.height / 2);\n  };\n\n  return (\n    <div\n      ref={cardRef}\n      onPointerMove={handlePointerMove}\n      onPointerLeave={handlePointerLeave}\n      className={`relative w-full overflow-hidden border select-none cursor-crosshair ${\n        isMobile ? "aspect-[4/3] rounded-xl" : "aspect-[16/9] rounded-2xl"\n      }`}\n      style={{\n        borderColor: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.08)",\n        backgroundColor: isDark ? "#090607" : "#f5edea",\n        boxShadow: isDark\n          ? "inset 0 1px 0 0 rgba(255,255,255,0.12), 0 8px 32px -4px rgba(0,0,0,0.5)"\n          : "inset 0 1px 0 0 rgba(255,255,255,0.8), 0 8px 24px -4px rgba(0,0,0,0.06)",\n      }}\n    >\n      {/* Top specular ray */}\n      <div className="absolute top-0 inset-x-0 h-px bg-gradient-to-r from-transparent via-white/20 to-transparent z-20 pointer-events-none" />\n\n      {/* Dim Base Texture */}\n      <div\n        className="absolute inset-0 opacity-40 pointer-events-none"\n        style={{\n          backgroundImage:\n            "radial-gradient(circle at 1px 1px, rgba(255,255,255,0.12) 1px, transparent 0), linear-gradient(135deg, rgba(0,0,0,0.6) 0%, transparent 100%)",\n          backgroundSize: "28px 28px, 100% 100%",\n        }}\n      />\n\n      {/* Lit Layer: High Specular Glaze & 24K Flecks revealed by mask */}\n      <motion.div\n        className="absolute inset-0 pointer-events-none"\n        style={{\n          maskImage: mask,\n          WebkitMaskImage: mask,\n          background: isDark\n            ? "radial-gradient(circle at center, rgba(225,29,72,0.3) 0%, rgba(251,191,36,0.12) 45%, transparent 75%)"\n            : "radial-gradient(circle at center, rgba(190,18,60,0.25) 0%, rgba(217,119,6,0.1) 45%, transparent 75%)",\n        }}\n      >\n        <div\n          className="absolute inset-0 opacity-70"\n          style={{\n            backgroundImage:\n              "radial-gradient(circle at 1px 1px, rgba(255,255,255,0.4) 1px, transparent 0)",\n            backgroundSize: "28px 28px",\n          }}\n        />\n\n        {/* Specular glints */}\n        <div\n          className="absolute top-1/4 left-1/3 w-2.5 h-2.5 rounded-full"\n          style={{ backgroundColor: "#fbbf24", boxShadow: "0 0 14px #fbbf24" }}\n        />\n        <div\n          className="absolute top-2/3 left-1/2 w-2 h-2 rounded-full"\n          style={{ backgroundColor: "#fef08a", boxShadow: "0 0 10px #fef08a" }}\n        />\n        <div\n          className="absolute top-1/2 right-1/4 w-3 h-3 rounded-full"\n          style={{ backgroundColor: "#fbbf24", boxShadow: "0 0 16px #fbbf24" }}\n        />\n      </motion.div>\n\n      {/* Label */}\n      <div className="absolute bottom-3 left-3 sm:bottom-5 sm:left-5 z-10 pointer-events-none space-y-0.5">\n        <span className="font-mono text-[9px] tracking-[0.2em] uppercase text-zinc-400 block">\n          Specular Glaze Lens\n        </span>\n        <span\n          className="text-[11px] font-semibold block"\n          style={{ color: isDark ? "#f4f4f5" : "#18181b" }}\n        >\n          Hover pointer to illuminate crystal structure\n        </span>\n      </div>\n    </div>\n  );\n}\n\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Tilt Card Component\n   \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nfunction TiltCard({\n  children,\n  onClick,\n  active,\n  isDark,\n  accent,\n  isMobile,\n}: {\n  children: React.ReactNode;\n  onClick: () => void;\n  active: boolean;\n  isDark: boolean;\n  accent: string;\n  isMobile: boolean;\n}) {\n  const rx = useSpring(0, TILT);\n  const ry = useSpring(0, TILT);\n  const [glarePos, setGlarePos] = useState({ x: 50, y: 50 });\n\n  const glare = useMotionTemplate`radial-gradient(circle at ${glarePos.x}% ${glarePos.y}%, rgba(255,255,255,0.14), transparent 55%)`;\n\n  return (\n    <motion.div\n      onClick={onClick}\n      onPointerMove={(e) => {\n        if (isMobile) return;\n        const r = e.currentTarget.getBoundingClientRect();\n        const px = (e.clientX - r.left) / r.width;\n        const py = (e.clientY - r.top) / r.height;\n        ry.set((px - 0.5) * 10);\n        rx.set(-(py - 0.5) * 10);\n        setGlarePos({ x: px * 100, y: py * 100 });\n      }}\n      onPointerLeave={() => {\n        rx.set(0);\n        ry.set(0);\n      }}\n      whileHover={isMobile ? undefined : { y: -4 }}\n      whileTap={{ scale: 0.98 }}\n      transition={SPRING}\n      style={{\n        rotateX: rx,\n        rotateY: ry,\n        transformPerspective: 900,\n        backgroundColor: isDark ? "rgba(255,255,255,0.03)" : "rgba(0,0,0,0.02)",\n        borderColor: active ? accent : isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.08)",\n        boxShadow: isDark\n          ? "inset 0 1px 0 0 rgba(255,255,255,0.1), 0 8px 32px -4px rgba(0,0,0,0.4)"\n          : "inset 0 1px 0 0 rgba(255,255,255,0.7), 0 8px 24px -4px rgba(0,0,0,0.04)",\n      }}\n      className={`relative border cursor-pointer overflow-hidden transition-colors ${\n        isMobile ? "p-4 rounded-xl" : "p-5 sm:p-6 rounded-2xl"\n      }`}\n    >\n      {/* Glare overlay */}\n      <motion.div\n        className="absolute inset-0 pointer-events-none"\n        style={{ backgroundImage: glare }}\n      />\n\n      {/* Top highlight */}\n      <div className="absolute top-0 inset-x-0 h-px bg-gradient-to-r from-transparent via-white/20 to-transparent pointer-events-none" />\n\n      {/* Active layoutId border indicator */}\n      {active && (\n        <motion.span\n          layoutId="edition-active-indicator"\n          transition={SPRING}\n          className={`absolute inset-0 pointer-events-none border-2 ${\n            isMobile ? "rounded-xl" : "rounded-2xl"\n          }`}\n          style={{ borderColor: accent }}\n        />\n      )}\n\n      <div className="relative z-10">{children}</div>\n    </motion.div>\n  );\n}\n\n/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   MAIN COMPONENT\n   \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\nexport default function AmarenaRoyaleTemplate({\n  brandName = "AMARENA ROYALE",\n  theme = "dark",\n  deviceMode = "desktop",\n}: {\n  brandName?: string;\n  theme?: string;\n  deviceMode?: "desktop" | "tablet" | "mobile";\n}) {\n  const isDark = theme === "dark";\n\n  /* Container width observation for preview frames */\n  const rootRef = useRef<HTMLDivElement>(null);\n  const heroRef = useRef<HTMLElement>(null);\n  const [containerWidth, setContainerWidth] = useState(1200);\n\n  useEffect(() => {\n    if (!rootRef.current) return;\n    const ro = new ResizeObserver((entries) => {\n      for (const entry of entries) {\n        setContainerWidth(entry.contentRect.width);\n      }\n    });\n    ro.observe(rootRef.current);\n    return () => ro.disconnect();\n  }, []);\n\n  const isMobile = deviceMode === "mobile" || containerWidth < 640;\n  const isTablet = deviceMode === "tablet" || (!isMobile && containerWidth < 1024);\n\n  /* State */\n  const [selectedEdition, setSelectedEdition] = useState<EditionKey>("royale");\n  const [boxSize, setBoxSize] = useState<4 | 8>(4);\n  const [reserved, setReserved] = useState(false);\n\n  const current = EDITIONS[selectedEdition];\n  const accent = isDark ? current.accentDark : current.accentLight;\n\n  /* Hero Parallax & Scroll Transforms */\n  const heroProgress = useScrollProgress(heroRef, "leave");\n  const heroSpring = useSpring(heroProgress, { stiffness: 140, damping: 28 });\n\n  const videoScale = useTransform(heroSpring, [0, 1], [1.06, 1.25]);\n  const videoBlur = useTransform(heroSpring, [0, 1], ["blur(0px)", "blur(14px)"]);\n  const videoBrightness = useTransform(heroSpring, [0, 1], [1, 0.35]);\n  const heroTextY = useTransform(heroSpring, [0, 1], [0, isMobile ? -24 : -60]);\n  const heroTextOpacity = useTransform(heroSpring, [0, 0.65], [1, 0]);\n\n  /* Pointer parallax in hero */\n  const heroX = useSpring(0, { stiffness: 200, damping: 25 });\n  const heroY = useSpring(0, { stiffness: 200, damping: 25 });\n\n  const handleHeroPointerMove = (e: React.PointerEvent<HTMLElement>) => {\n    if (isMobile) return;\n    if (!heroRef.current) return;\n    const r = heroRef.current.getBoundingClientRect();\n    heroX.set((e.clientX - (r.left + r.width / 2)) * 0.04);\n    heroY.set((e.clientY - (r.top + r.height / 2)) * 0.04);\n  };\n\n  const handleHeroPointerLeave = () => {\n    heroX.set(0);\n    heroY.set(0);\n  };\n\n  /* Header scroll progress */\n  const pageProgress = useScrollProgress(rootRef, "track");\n  const headerSpring = useSpring(pageProgress, { stiffness: 200, damping: 30 });\n  const progressScaleX = useTransform(headerSpring, [0, 1], [0, 1]);\n\n  const scrollToSection = (id: string) => {\n    if (!rootRef.current) return;\n    const el = rootRef.current.querySelector(`#${id}`);\n    if (el) {\n      el.scrollIntoView({ behavior: "smooth" });\n    }\n  };\n\n  const handleReserve = () => {\n    setReserved(true);\n    setTimeout(() => setReserved(false), 3500);\n  };\n\n  const activePrice = boxSize === 4 ? current.priceFour : current.priceEight;\n\n  return (\n    <div\n      ref={rootRef}\n      className="relative w-full overflow-x-clip transition-colors duration-300 font-sans select-none"\n      style={{\n        backgroundColor: isDark ? "#09090b" : "#fafafa",\n        color: isDark ? "#f4f4f5" : "#18181b",\n      }}\n    >\n      {/* \u2500\u2500\u2500 HEADER \u2500\u2500\u2500 */}\n      <header\n        className={`sticky top-0 z-50 flex items-center justify-between border-b backdrop-blur-xl transition-colors duration-300 ${\n          isMobile\n            ? "h-14 px-4 -mb-14"\n            : isTablet\n            ? "h-16 px-6 -mb-16"\n            : "h-20 px-10 -mb-20"\n        }`}\n        style={{\n          backgroundColor: isDark ? "rgba(9, 9, 11, 0.82)" : "rgba(250, 250, 250, 0.85)",\n          borderColor: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.08)",\n        }}\n      >\n        <span\n          className={`font-black tracking-widest uppercase ${\n            isMobile ? "text-xs" : "text-sm"\n          }`}\n        >\n          {brandName || "AMARENA ROYALE"}\n        </span>\n\n        {!isMobile && !isTablet && (\n          <nav className="flex items-center gap-8 text-xs text-zinc-400">\n            <button\n              type="button"\n              onClick={() => scrollToSection("cleave")}\n              className="hover:text-zinc-100 transition-colors cursor-pointer"\n            >\n              Cross-section\n            </button>\n            <button\n              type="button"\n              onClick={() => scrollToSection("glaze")}\n              className="hover:text-zinc-100 transition-colors cursor-pointer"\n            >\n              Glaze\n            </button>\n            <button\n              type="button"\n              onClick={() => scrollToSection("editions")}\n              className="hover:text-zinc-100 transition-colors cursor-pointer"\n            >\n              Editions\n            </button>\n          </nav>\n        )}\n\n        <button\n          type="button"\n          onClick={() => scrollToSection("reserve")}\n          className={`rounded-lg font-semibold transition-all cursor-pointer border ${\n            isMobile ? "px-2.5 py-1 text-[11px]" : "px-4 py-2 text-xs"\n          }`}\n          style={{\n            backgroundColor: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.05)",\n            borderColor: isDark ? "rgba(255,255,255,0.12)" : "rgba(0,0,0,0.12)",\n            color: isDark ? "#f4f4f5" : "#18181b",\n          }}\n        >\n          Reserve Box\n        </button>\n\n        {/* Scroll Progress Line */}\n        <motion.div\n          className="absolute bottom-0 left-0 right-0 h-[2px] origin-left"\n          style={{\n            scaleX: progressScaleX,\n            backgroundColor: accent,\n          }}\n        />\n      </header>\n\n      {/* \u2500\u2500\u2500 SECTION 1: HERO \u2500\u2500\u2500 */}\n      <section\n        ref={heroRef}\n        onPointerMove={handleHeroPointerMove}\n        onPointerLeave={handleHeroPointerLeave}\n        className={`relative flex flex-col justify-between overflow-hidden ${\n          isMobile\n            ? "h-[500px] pt-16 pb-4 px-4"\n            : isTablet\n            ? "h-[620px] pt-20 pb-8 px-6"\n            : "min-h-[92vh] pt-32 pb-12 px-10"\n        }`}\n      >\n        {/* Full-bleed Video Media */}\n        <div className="absolute inset-0 z-0 pointer-events-none overflow-hidden">\n          <motion.video\n            src="/videos/amarena-royale-cupcake.mp4"\n            autoPlay\n            loop\n            muted\n            playsInline\n            preload="auto"\n            className="w-full h-full object-cover object-center"\n            style={{\n              scale: videoScale,\n              filter: videoBlur,\n              opacity: videoBrightness,\n              x: heroX,\n              y: heroY,\n            }}\n          />\n\n          {/* Neutral Atmospheric Vignette */}\n          <div\n            className="absolute inset-0"\n            style={{\n              background: isDark\n                ? "linear-gradient(to bottom, rgba(9,9,11,0.65) 0%, rgba(9,9,11,0.2) 40%, rgba(9,9,11,0.7) 75%, #09090b 100%)"\n                : "linear-gradient(to bottom, rgba(250,250,250,0.65) 0%, rgba(250,250,250,0.2) 40%, rgba(250,250,250,0.7) 75%, #fafafa 100%)",\n            }}\n          />\n        </div>\n\n        {/* Spacer */}\n        <div className="relative z-10" />\n\n        {/* Monumental Headline */}\n        <motion.div\n          style={{ y: heroTextY, opacity: heroTextOpacity }}\n          className={`relative z-10 max-w-4xl ${isMobile ? "space-y-2 my-auto" : "space-y-4"}`}\n        >\n          <h1\n            className={`font-black tracking-[-0.04em] leading-[0.92] uppercase ${\n              isMobile\n                ? "text-3xl"\n                : isTablet\n                ? "text-5xl"\n                : "text-7xl lg:text-8xl"\n            }`}\n          >\n            <div className="flex flex-col">\n              <span className="block"><SplitWords text="AMARENA" /></span>\n              <span className="block"><SplitWords text="ROYALE" /></span>\n            </div>\n          </h1>\n\n          <p\n            className={`text-zinc-400 leading-relaxed ${\n              isMobile ? "text-xs max-w-xs" : isTablet ? "text-sm max-w-sm" : "text-base max-w-lg"\n            }`}\n          >\n            Grand Cru Venezuelan cacao, steeped wild cherries, Madagascar chantilly.\n          </p>\n        </motion.div>\n\n        {/* 3 Counted Numbers */}\n        <motion.div\n          className={`relative z-10 grid grid-cols-3 border-t ${\n            isMobile ? "gap-2 pt-3 pb-1" : isTablet ? "gap-4 pt-6 pb-2" : "gap-6 pt-10"\n          }`}\n          style={{\n            opacity: heroTextOpacity,\n            borderColor: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.08)",\n          }}\n        >\n          {STATS.map((s, idx) => (\n            <div key={s.label} className="space-y-0.5">\n              <div\n                className={`font-black tracking-tight tabular-nums ${\n                  isMobile\n                    ? "text-lg"\n                    : isTablet\n                    ? "text-2xl"\n                    : "text-3xl lg:text-4xl"\n                }`}\n                style={{ color: isDark ? "#f4f4f5" : "#18181b" }}\n              >\n                <Counter to={s.figure} suffix={s.suffix} delay={0.2 * idx} />\n              </div>\n              <p\n                className={`font-mono text-zinc-500 uppercase tracking-wider ${\n                  isMobile ? "text-[8px]" : isTablet ? "text-[10px]" : "text-xs"\n                }`}\n              >\n                {s.label}\n              </p>\n            </div>\n          ))}\n        </motion.div>\n      </section>\n\n      {/* \u2500\u2500\u2500 SECTION 2: THE WOW MOMENT (CLEAVE SLIDER) \u2500\u2500\u2500 */}\n      <section\n        id="cleave"\n        className={`w-full max-w-6xl mx-auto ${\n          isMobile\n            ? "px-4 py-12 space-y-4"\n            : isTablet\n            ? "px-6 py-20 space-y-8"\n            : "px-10 py-32 space-y-10"\n        }`}\n      >\n        <div className="space-y-1.5 max-w-2xl">\n          <h2\n            className={`font-black tracking-[-0.03em] leading-tight ${\n              isMobile ? "text-2xl" : isTablet ? "text-3xl" : "text-4xl lg:text-5xl"\n            }`}\n          >\n            The cross-section.\n          </h2>\n          <p\n            className={`text-zinc-400 leading-relaxed ${\n              isMobile ? "text-xs" : "text-sm sm:text-base"\n            }`}\n          >\n            Slice through the 70% dark shell to inspect the aeration and molten core.\n          </p>\n        </div>\n\n        <CleaveInspector\n          isDark={isDark}\n          accent={accent}\n          isMobile={isMobile}\n          isTablet={isTablet}\n        />\n      </section>\n\n      {/* \u2500\u2500\u2500 SECTION 3: DETAIL (CURSOR-LIT GLAZE) \u2500\u2500\u2500 */}\n      <section\n        id="glaze"\n        className={`w-full max-w-6xl mx-auto ${\n          isMobile\n            ? "px-4 py-12 space-y-4"\n            : isTablet\n            ? "px-6 py-20 space-y-8"\n            : "px-10 py-28 space-y-10"\n        }`}\n      >\n        <div className="space-y-1.5 max-w-2xl">\n          <h2\n            className={`font-black tracking-[-0.03em] leading-tight ${\n              isMobile ? "text-2xl" : isTablet ? "text-3xl" : "text-4xl lg:text-5xl"\n            }`}\n          >\n            Cursor-lit glaze.\n          </h2>\n          <p\n            className={`text-zinc-400 leading-relaxed ${\n              isMobile ? "text-xs" : "text-sm sm:text-base"\n            }`}\n          >\n            Move your pointer across the surface to inspect the tempered gloss and gold leaf.\n          </p>\n        </div>\n\n        <div\n          className={\n            isMobile || isTablet\n              ? "flex flex-col gap-4"\n              : "grid grid-cols-12 gap-8 items-center"\n          }\n        >\n          <div className={isMobile || isTablet ? "w-full" : "col-span-8"}>\n            <CursorLitMaterial\n              isDark={isDark}\n              accent={accent}\n              isMobile={isMobile}\n            />\n          </div>\n\n          <div\n            className={\n              isMobile || isTablet\n                ? "w-full grid grid-cols-1 gap-2.5"\n                : "col-span-4 space-y-4"\n            }\n          >\n            <div\n              className={`rounded-xl border space-y-1.5 ${\n                isMobile ? "p-3.5" : "p-5 sm:p-6 rounded-2xl"\n              }`}\n              style={{\n                backgroundColor: isDark ? "rgba(255,255,255,0.02)" : "rgba(0,0,0,0.02)",\n                borderColor: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.06)",\n              }}\n            >\n              <span className="font-mono text-xs font-bold" style={{ color: accent }}>\n                31.5\xB0C\n              </span>\n              <h3\n                className="text-xs sm:text-sm font-semibold tracking-tight"\n                style={{ color: isDark ? "#f4f4f5" : "#18181b" }}\n              >\n                Stable Beta-V Temper\n              </h3>\n              <p className="text-[11px] sm:text-xs text-zinc-400 leading-relaxed">\n                Controlled cooling locks the cocoa butter crystals into uniform lattice, giving the mirror sheen and clean snap.\n              </p>\n            </div>\n\n            <div\n              className={`rounded-xl border space-y-1.5 ${\n                isMobile ? "p-3.5" : "p-5 sm:p-6 rounded-2xl"\n              }`}\n              style={{\n                backgroundColor: isDark ? "rgba(255,255,255,0.02)" : "rgba(0,0,0,0.02)",\n                borderColor: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.06)",\n              }}\n            >\n              <span className="font-mono text-xs font-bold" style={{ color: accent }}>\n                24-Karat\n              </span>\n              <h3\n                className="text-xs sm:text-sm font-semibold tracking-tight"\n                style={{ color: isDark ? "#f4f4f5" : "#18181b" }}\n              >\n                Edible Gold Leafing\n              </h3>\n              <p className="text-[11px] sm:text-xs text-zinc-400 leading-relaxed">\n                Hammered gold leaves applied by hand onto the warm glaze prior to cooling, catching ambient light reflections.\n              </p>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      {/* \u2500\u2500\u2500 SECTION 4: CHOICE (EDITIONS) \u2500\u2500\u2500 */}\n      <section\n        id="editions"\n        className={`w-full max-w-6xl mx-auto ${\n          isMobile\n            ? "px-4 py-12 space-y-4"\n            : isTablet\n            ? "px-6 py-20 space-y-8"\n            : "px-10 py-32 space-y-10"\n        }`}\n      >\n        <div className="space-y-1.5 max-w-2xl">\n          <h2\n            className={`font-black tracking-[-0.03em] leading-tight ${\n              isMobile ? "text-2xl" : isTablet ? "text-3xl" : "text-4xl lg:text-5xl"\n            }`}\n          >\n            Three compositions.\n          </h2>\n          <p\n            className={`text-zinc-400 leading-relaxed ${\n              isMobile ? "text-xs" : "text-sm sm:text-base"\n            }`}\n          >\n            Each edition is balanced for a distinct chocolate and cherry profile.\n          </p>\n        </div>\n\n        <div\n          className={`grid ${\n            isMobile\n              ? "grid-cols-1 gap-3"\n              : isTablet\n              ? "grid-cols-3 gap-3"\n              : "grid-cols-3 gap-6"\n          }`}\n        >\n          {(["royale", "chantilly", "noir"] as const).map((key) => {\n            const ed = EDITIONS[key];\n            const active = selectedEdition === key;\n            return (\n              <TiltCard\n                key={ed.id}\n                active={active}\n                isDark={isDark}\n                accent={accent}\n                isMobile={isMobile}\n                onClick={() => setSelectedEdition(key)}\n              >\n                <div className="space-y-2.5 sm:space-y-4">\n                  <div className="flex items-center justify-between">\n                    <span className="font-mono text-[9px] sm:text-[10px] tracking-widest uppercase text-zinc-500">\n                      {ed.cacao}\n                    </span>\n                    <span\n                      className="w-2.5 h-2.5 rounded-full"\n                      style={{ backgroundColor: isDark ? ed.accentDark : ed.accentLight }}\n                    />\n                  </div>\n\n                  <h3\n                    className="text-sm sm:text-base md:text-lg font-bold tracking-tight"\n                    style={{ color: isDark ? "#f4f4f5" : "#18181b" }}\n                  >\n                    {ed.name}\n                  </h3>\n\n                  <p className="text-[11px] sm:text-xs text-zinc-400 leading-relaxed">\n                    {ed.tagline}\n                  </p>\n\n                  <div\n                    className="pt-2 sm:pt-4 border-t flex justify-between items-center text-xs font-mono text-zinc-500"\n                    style={{ borderColor: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.06)" }}\n                  >\n                    <span>From ${ed.priceFour}</span>\n                    <span className="capitalize">{active ? "Selected" : "Select"}</span>\n                  </div>\n                </div>\n              </TiltCard>\n            );\n          })}\n        </div>\n\n        {/* Selected Composition Callout */}\n        <div\n          className={`border flex justify-between ${\n            isMobile\n              ? "p-4 rounded-xl flex-col gap-2"\n              : "p-6 rounded-2xl flex-row items-center gap-4"\n          }`}\n          style={{\n            backgroundColor: isDark ? "rgba(255,255,255,0.02)" : "rgba(0,0,0,0.02)",\n            borderColor: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.06)",\n          }}\n        >\n          <div className="space-y-1">\n            <span className="font-mono text-[9px] text-zinc-500 uppercase tracking-widest">\n              Selected Edition Details\n            </span>\n            <p className="text-xs sm:text-sm text-zinc-300 max-w-xl">\n              {current.notes}\n            </p>\n          </div>\n          <div className="font-mono text-[10px] sm:text-xs text-zinc-400 shrink-0">\n            Handcrafted in small morning batches\n          </div>\n        </div>\n      </section>\n\n      {/* \u2500\u2500\u2500 SECTION 5: ACTION (RESERVATION CARD) \u2500\u2500\u2500 */}\n      <section\n        id="reserve"\n        className={`w-full max-w-3xl mx-auto ${\n          isMobile\n            ? "px-4 py-12"\n            : isTablet\n            ? "px-6 py-20"\n            : "px-10 py-32"\n        }`}\n      >\n        <div\n          className={`border relative overflow-hidden ${\n            isMobile\n              ? "p-5 rounded-2xl space-y-5"\n              : isTablet\n              ? "p-8 rounded-2xl space-y-6"\n              : "p-12 rounded-3xl space-y-8"\n          }`}\n          style={{\n            backgroundColor: isDark ? "rgba(255,255,255,0.03)" : "rgba(0,0,0,0.02)",\n            borderColor: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.08)",\n            boxShadow: isDark\n              ? "inset 0 1px 0 0 rgba(255,255,255,0.12), 0 8px 32px -4px rgba(0,0,0,0.5)"\n              : "inset 0 1px 0 0 rgba(255,255,255,0.8), 0 8px 24px -4px rgba(0,0,0,0.06)",\n          }}\n        >\n          {/* Top specular highlight */}\n          <div className="absolute top-0 inset-x-0 h-px bg-gradient-to-r from-transparent via-white/25 to-transparent pointer-events-none" />\n\n          <div className="space-y-1.5">\n            <h2\n              className={`font-black tracking-[-0.03em] leading-tight ${\n                isMobile ? "text-2xl" : "text-3xl lg:text-4xl"\n              }`}\n            >\n              Reserve a box.\n            </h2>\n            <p className="text-xs sm:text-sm text-zinc-400 leading-relaxed">\n              Dispatched daily in chilled isothermal packaging across Paris and Bologna.\n            </p>\n          </div>\n\n          {/* Size Choice with layoutId */}\n          <div className="space-y-1.5">\n            <label className="font-mono text-[9px] text-zinc-500 uppercase tracking-widest block">\n              Box Quantity\n            </label>\n            <div\n              className={`grid p-1 rounded-xl border ${\n                isMobile ? "grid-cols-1 gap-2" : "grid-cols-2 gap-3"\n              }`}\n              style={{\n                backgroundColor: isDark ? "rgba(0,0,0,0.2)" : "rgba(0,0,0,0.02)",\n                borderColor: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.06)",\n              }}\n            >\n              {[\n                { size: 4 as const, label: "Box of 4 Pieces", price: current.priceFour },\n                { size: 8 as const, label: "Box of 8 Pieces", price: current.priceEight },\n              ].map((item) => {\n                const active = boxSize === item.size;\n                return (\n                  <button\n                    key={item.size}\n                    type="button"\n                    onClick={() => setBoxSize(item.size)}\n                    className="relative py-2.5 px-3 sm:px-4 rounded-lg text-xs font-semibold flex items-center justify-between cursor-pointer transition-colors"\n                    style={{\n                      color: active\n                        ? isDark ? "#ffffff" : "#09090b"\n                        : isDark ? "#a1a1aa" : "#71717a",\n                    }}\n                  >\n                    {active && (\n                      <motion.span\n                        layoutId="box-size-pill"\n                        transition={SPRING}\n                        className="absolute inset-0 rounded-lg shadow-sm"\n                        style={{\n                          backgroundColor: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.06)",\n                        }}\n                      />\n                    )}\n                    <span className="relative z-10">{item.label}</span>\n                    <span className="relative z-10 font-mono">${item.price}</span>\n                  </button>\n                );\n              })}\n            </div>\n          </div>\n\n          {/* Summary Details */}\n          <div\n            className="space-y-1 text-xs font-mono text-zinc-400 pt-2 border-t"\n            style={{ borderColor: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.06)" }}\n          >\n            <div className="flex justify-between">\n              <span>Selected Composition:</span>\n              <span className="font-semibold" style={{ color: isDark ? "#f4f4f5" : "#18181b" }}>\n                {current.name}\n              </span>\n            </div>\n            <div className="flex justify-between">\n              <span>Storage Life:</span>\n              <span>48h chilled at 4\xB0C</span>\n            </div>\n            <div className="flex justify-between">\n              <span>Delivery Method:</span>\n              <span>Same-day temperature controlled</span>\n            </div>\n          </div>\n\n          {/* Magnetic CTA Button */}\n          <div className="pt-1">\n            <MagneticButton\n              onClick={handleReserve}\n              className="w-full py-3.5 sm:py-4 px-4 sm:px-6 rounded-xl font-bold text-xs sm:text-sm text-white flex items-center justify-center gap-2 cursor-pointer transition-opacity hover:opacity-95 shadow-lg border"\n              style={{\n                backgroundColor: accent,\n                borderColor: "rgba(255,255,255,0.2)",\n              }}\n            >\n              <AnimatePresence mode="wait">\n                {reserved ? (\n                  <motion.span\n                    key="booked"\n                    initial={{ opacity: 0, y: 8 }}\n                    animate={{ opacity: 1, y: 0 }}\n                    exit={{ opacity: 0, y: -8 }}\n                    transition={SPRING}\n                    className="flex items-center gap-2"\n                  >\n                    <Check className="w-4 h-4" />\n                    <span>Reserved \u2022 Scheduled for courier</span>\n                  </motion.span>\n                ) : (\n                  <motion.span\n                    key="idle"\n                    initial={{ opacity: 0, y: 8 }}\n                    animate={{ opacity: 1, y: 0 }}\n                    exit={{ opacity: 0, y: -8 }}\n                    transition={SPRING}\n                    className="flex items-center gap-2"\n                  >\n                    <span>Reserve Box \u2014 ${activePrice}</span>\n                    <ArrowRight className="w-4 h-4" />\n                  </motion.span>\n                )}\n              </AnimatePresence>\n            </MagneticButton>\n          </div>\n        </div>\n      </section>\n\n      {/* \u2500\u2500\u2500 FOOTER \u2500\u2500\u2500 */}\n      <footer\n        className={`w-full border-t text-center ${\n          isMobile ? "py-4 px-4" : "py-8 px-10"\n        }`}\n        style={{\n          borderColor: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.08)",\n          color: isDark ? "#71717a" : "#a1a1aa",\n        }}\n      >\n        <p className="font-mono text-[10px] sm:text-[11px]">\n          Amarena Royale P\xE2tisserie. Paris & Bologna. Handcrafted daily.\n        </p>\n      </footer>\n    </div>\n  );\n}\n'
};

